window.TEXT5_DATA = {"2010-07": [{"head": "電気店のカメラ売り場で女の人が店員と話しています。", "lines": [{"k": "spk", "s": "女", "t": "デジタルカメラを買いたいんですが。できるだけ、小型で、軽くて、う~ん、予算は3万円までで。"}, {"k": "spk", "s": "男", "t": "え~と。小型で人気があるのは、桜カメラのこれですね。価格が3万2千円になってしまうんですが、もともと4万5千円の商品ですから、お買い得ですよ。"}, {"k": "spk", "s": "女", "t": "は~あ。"}, {"k": "spk", "s": "男", "t": "このグリーンカメラのは、プリンターがおまけについて、ちょうど3万円です。別々に買えば、5万円は軽く超えます。絶対、お得ですよ。スターカメラのも、小さくて、軽いですよ。基本的な機能だけなんですが、その分お値段は2万3千円と抑えられています。"}, {"k": "spk", "s": "女", "t": "う~ん。"}, {"k": "spk", "s": "男", "t": "あとは、光カメラのこれですね。ご覧とおり、便利な機能が満載です。ただいま、キャンペーン中で、3万4千円となっています。"}, {"k": "spk", "s": "女", "t": "う~ん、でも、予算は超えたくないし、いらない機能やおまけがついてても、使わないのよねえ。じゃ、これにします女の人はどの会社のカメラを買いますか。(1)桜カメラ。(2)グリーンカメラ(3)スターカメラ。(4)光カメラ。"}]}, {"head": "車を買うかどうかについて、家族三人で相談しています。", "lines": [{"k": "spk", "s": "男", "t": "ねえ、最近車の調子がおかしいんだけど、そろそろ寿命かな"}, {"k": "spk", "s": "女", "t": "お父さん、新しい車買うの~だったら、今度は絶対大きい車にしようよ。スキーに行くときも便利だし。"}, {"k": "spk", "s": "女2", "t": "ちょっと待って、前から考えてたんだけど、車って、本当に必要かしら。私はなくても困らないわ"}, {"k": "spk", "s": "男", "t": "うん、そうだね。燃料も高くなってるし、保険も上がったしね、維持が大変だよな。"}, {"k": "spk", "s": "女2", "t": "そうよ。今ある車庫のスペース、畑にしたらどうかしら、環境にも家計にもやさしいし。"}, {"k": "spk", "s": "女", "t": "えつ、ってことは、いつものドライプは、なくなるってこと~そんなのないよ~"}, {"k": "spk", "s": "女2", "t": "そうよ、家族でハイキングでもしたほうが、健康にもいいわ"}, {"k": "spk", "s": "女", "t": "あっ、でも、お婆ちゃんをどっかにつれてってあげる時はどうすま病院とか車がないと困るよ"}, {"k": "spk", "s": "男", "t": "あっ、そうだよ。そのことが最優先だね。"}, {"k": "spk", "s": "女2", "t": "そうだったわね。"}, {"k": "q", "t": "車を買うかどうかを決めるときに、一番大切な問題は何ですか。"}, {"k": "ch", "t": "1.家族のレジャー"}, {"k": "ch", "t": "2.車の維持費"}, {"k": "ch", "t": "3.環境の保護"}, {"k": "ch", "t": "4.家族の送迎"}]}, {"head": "テレビを見ながら、男の人と女の人が話しています。", "lines": [{"k": "text", "t": "テレビの男:さて、次は読書コーナーの時間です。今日はことし、特に話題になった小説をジャンル別にご紹介します。まず、時代小説ですが、なんといっても、『タ暮れの川』ですね。江戸時代の庶民の暮らしを鮮やかに描いたものです。次に、推理小説では、2人の刑事の活躍が読者を楽しませてくれる。『ハードアンドソフト』を、お勧めします。これはすでに百万部を突破し、今年度、出版界最大のヒット作となっています。『青と緑』は、若い男女の微妙な心理を巧みに描写した恋愛小説で、現在人気上昇中です。最後に、ビジネス小説の分野ては『ネオ銀行の再生』がマスコミに頻繁に取り上げられ、注目を集めています。"}, {"k": "spk", "s": "男", "t": "ねえ、吉田さんはどんな本が好きなの。"}, {"k": "spk", "s": "女", "t": "わたし~わたしは本がせんせん。恋愛とか歴史とかは特にだめね。"}, {"k": "spk", "s": "男", "t": "そうなんた"}, {"k": "spk", "s": "女", "t": "でも、このビジネス小説、おもしろそう。仕事に役立ちそうだし。買って読んでみようかな田中さんは~"}, {"k": "spk", "s": "男", "t": "僕は本なら、ジャンルを問わず、何でもすきなんだ"}, {"k": "spk", "s": "女", "t": "ええ、じゃ、今のテレビで言ってた本も全部読んでるの。男.いや、一番売れているって言ってた本はまだだけどね女の人はどの本を読もうと思0ていますか。解答4"}, {"k": "q", "t": "質問2男の人がまだ読んでいない小説はどれですか。解答2"}]}], "2010-12": [{"head": "会社で男の人と女の人がリストを見ながら話しています。", "lines": [{"k": "spk", "s": "男", "t": "今度の新製品のデザイナー誰にする~なるべくコストを抑えたいから新人で、将来性があって、それと今回の仕事は納期が厳しいから締め切りきちんと守れる人じゃないと駄目だな。"}, {"k": "spk", "s": "女", "t": "はい、こちらが新人デザイナーのリストですが。まず一番の人ですが、彼は仕事に慣れていますし、将来背もあります。それと締め切りのほうはぎりぎりのこともありますが、これまでは必ず間に合わせてくれてます。"}, {"k": "spk", "s": "男", "t": "うんうん。"}, {"k": "spk", "s": "女", "t": "次の二番の人は斬新なデザインが好評です。ただ、納期の面ではちょっと。捨てがたい人材なんですが。"}, {"k": "spk", "s": "男", "t": "そうか。"}, {"k": "spk", "s": "女", "t": "同じく三番の人は作品はなかなかいいんですが、締め切りのほうは過ぎてしまうことがあるようです。それからこの四番の人は納期はいつも問題ないんですが、この間デザイナー賞をとったんで、デサイン料がかなりあがっちゃってるんですよ。コストがかかりすきますね。"}, {"k": "spk", "s": "男", "t": "うーん、そうだね。やつばりコストと納期はゆずれないよな。じゃ、この人にお願いしようか。"}, {"k": "spk", "s": "女", "t": "はい、では、早速連絡いたします。"}, {"k": "q", "t": "問い新製品のデザインは誰に頼みますか。"}, {"k": "ch", "t": "1. 1番の人2.2番の人"}, {"k": "ch", "t": "3. 3番の人"}, {"k": "ch", "t": "4. 4番の人"}]}, {"head": "スポーッショップで店員と大学生の姉と弟が話しています。", "lines": [{"k": "spk", "s": "店員", "t": "いらっしゃいませ何かお探しでしょうか。"}, {"k": "spk", "s": "姉", "t": "誕生日のプレゼントなんですけどね、母が最近テニスを始めて何か使えるものをあげたいんです"}, {"k": "spk", "s": "店員", "t": "テニスウェアはこちらにございます。こちらの黒いウェアは新素材を使っておりまして大変人気がございます。デザインも若々しいですし、ほかの色もございます。お母様にもきっと気に入っていただけると思いますが"}, {"k": "spk", "s": "姉", "t": "いいじゃない。この黒の。今年の流行は黒だし。"}, {"k": "spk", "s": "弟", "t": "でも、母さんピンクが好きでよく着てるじゃない。このヒンクのがいいよ。"}, {"k": "spk", "s": "姉", "t": "たまには違う色もいいんじゃない。弟.ええ。そういえば母さんテニス用の靴持ってなかったよな。"}, {"k": "spk", "s": "店員", "t": "では、こちらへ。こちらなんかはお手ごろですよ。ピンクのもございますよ。もちろん流行の黒も。先ほどのウ=アと同じプランドの靴ですので、おいでお求めいただけますと素敵かと思います"}, {"k": "spk", "s": "弟", "t": "ふん、姉さん、これ籍朝するよ"}, {"k": "spk", "s": "姉", "t": "ほんとだ。うーん、やつばりさっきのにしようか。"}, {"k": "spk", "s": "弟", "t": "そうだね。色は母さんの好きなのがいいんじゃない。うん。着てもらえなかったら悲しいしね"}, {"k": "q", "t": "問い母親への贈り物は何になりましたか。"}, {"k": "text", "t": "1黒い服2ピンクの服3黒い靴4ピンクの靴"}]}, {"head": "会社で上司が研修の説明をしています。", "lines": [{"k": "spk", "s": "男", "t": "ええ、皆さんは入社して一年たったわけですが、今後わが社の戦力としてますます活躍する人材になってもらうよう研修を行うことにしました。研修は四つ用意しています。必ずーっ受けてください。まず、研修1ですが、基本的なビジネスマナーの再確認、プレゼンテーションの方法、ビジネス上の問題解決方法など総合的に研修します。これは二日間ですが、これ以外の三つは一日のみです。ええ、研修2ですが、グループワークを通して自分の行動の傾向を知り、コミュニケーションスキルを学ぶものです。次に研修3。研修3はビジネス敬語電話応対のスキルをさらに向上させるものです。そして研修4ですが、これはプレゼンのスキル向上に特化した研修です。以上四つの中から希望するものを一つ選んで受講してください。"}, {"k": "spk", "s": "女", "t": "どれを受ける~"}, {"k": "spk", "s": "男", "t": "そうだなあ、僕はチームで仕事をすることが多いからどうすればコミュニケーションがうまくいくかを勉強するよ"}, {"k": "spk", "s": "女", "t": "そう、わたしはプレゼンが苦手なのよね。だからこの機会にちゃんと練習したいなあ。あと、てきればビジネスマナーももう一度復習したいし、しつかり二日間勉強しよう。"}, {"k": "spk", "s": "男", "t": "あっ、でも、課長が今は仕事が忙しいから、なるべく一日のみの研修を選んで欲しいっていってたじゃない。"}, {"k": "spk", "s": "女", "t": "あっ、そうだった。じゃあ、決めた。今回は苦手克服のために頑張ることにする。"}, {"k": "q", "t": "質問1男の人はどの研修を選びましたか。解答2"}, {"k": "q", "t": "質問2女の人はどの研修を選びましたか。解答4"}]}], "2011-07": [{"head": "大学の就職課で女の学生と係りの人が話しています。", "lines": [{"k": "spk", "s": "女", "t": "来年から就職活動を始めるんですが、インターンシップって就職に有利って聞いたんですけど"}, {"k": "spk", "s": "男", "t": "有利っていうことはありませんけどね。でも、働くことを実際に体験できるいいチャンスではありますよ。いくつかタイプがあります。"}, {"k": "spk", "s": "女", "t": "あっ、そうですか。あのう、実は私、まだ職種が絞れてなくて、できるだけ広く見たいなと思ってるんですけど男・"}, {"k": "spk", "s": "女", "t": "それと、お金がもらえるのもあるって聞いたんですけど。"}, {"k": "spk", "s": "男", "t": "ああ、それは社員とほぼ同じ仕事をする実践タイプです。数週間から数ヶ月が一般的ですね。特別な技能やハイレベルの知識が必要で、誰でもってわけにはいかないけど。"}, {"k": "spk", "s": "女", "t": "はあ、ワープロとかじゃ、だめですよね。"}, {"k": "spk", "s": "男", "t": "そうですね。"}, {"k": "spk", "s": "女", "t": "てきれば、短時間でいろいろ体験できるといいんですけど"}, {"k": "spk", "s": "男", "t": "そうですか。いろんな企業を見たいなら、セミナータイプがいいですよ。平日の一日か二日で会社の中を見て回ったり、セミナーに参加したりするんですよ。ええと、それから、二週間程度なら、体験タイプがあります。営業の人と一緒に外回りしたりします。あ、たた、これはある程度やりたい仕事が決まっている人に向いていますね。"}, {"k": "spk", "s": "女", "t": "いろいろあるんですね。"}, {"k": "spk", "s": "男", "t": "あとは、あそこにポスターが貼ってありますけど、出身地に帰って、そこの企業で研修する、地元タイプもあります。ーケ月程度が一般的かな"}, {"k": "spk", "s": "女", "t": "同じところに一ヶ月ですか。それなら、いろんな会社を見てみたいから、これにします。"}, {"k": "q", "t": "女の学生はどのタイプのインターンシップに応募しますか。"}, {"k": "ch", "t": "1.実践タイプ"}, {"k": "ch", "t": "2.セミナータイプ"}, {"k": "ch", "t": "3.体験タイプ"}, {"k": "ch", "t": "4.地元タイプ"}]}, {"head": "運送会社の会議で話しています。", "lines": [{"k": "spk", "s": "男1", "t": "最近、荷物の配送の遅れが目立っているようなんだ。何かいい案はないかね。"}, {"k": "spk", "s": "男2", "t": "今の配達ルートを使うと、渋滞に巻き込まれるようですよ。安全検収の時にドライバーが言ってました"}, {"k": "spk", "s": "男1", "t": "そうか。"}, {"k": "spk", "s": "女", "t": "じゃあ、別のルートを考えて、渋滞を避けるようにしたらどうでしょうか。男1・他にいい道はあるかな"}, {"k": "spk", "s": "男2", "t": "それより、朝やってる荷物の積み込みを、夕方帰宅前にすれば、一時間は早く配達に出られますよね。男1・一時間ぐらい早く出てもなあ。あの渋滞はもっと早くから始まってるから"}, {"k": "spk", "s": "男2", "t": "だったら、出勤時間も早くすればどうでしょう。"}, {"k": "spk", "s": "男1", "t": "しかしね、出勤時間が早くなるのは、いろいろ難しいんじゃないかな"}, {"k": "spk", "s": "男2", "t": "ああ、そうですね。うん。"}, {"k": "spk", "s": "女", "t": "あのう、でしたら、今の配達ルートを決めたのは、もう随分前ですから。"}, {"k": "spk", "s": "男1", "t": "そうか、じゃあ、やつばりそこを検討だな。問題を解決するために、何を見直すことにしましたか。"}, {"k": "ch", "t": "1.ドライバーの検収方法2配達ルート"}, {"k": "ch", "t": "3.荷物を積み込む時間"}, {"k": "ch", "t": "4.朝の出勤時間"}]}, {"head": "テレビで男の人が話しています。", "lines": [{"k": "spk", "s": "男1", "t": "携帯電話会社が未来の携帯電話のアイディアを募集したところ、1万点を上回る応募があったそうです。今日はその中から、優秀賞に選ばれた四つのアイディアについてご紹介しましょう。ます、一番のアイディアは、腕時計型です。一見普通の時計に見えますが、ベルト部分が電話になっています。一番はべン型のもの。すこし大きめのペンという感じで、ポケットに挿しておけます。もちろん、ペンとしても使えます。三番は、名刺サイズのカード型のものです。薄いですし、ちょっと見ただけでは、カードと間違ってしまいそうですね。最後の四番のアイディアは、ハンカチ型の携帯です。ハンカチを広げたサイズなので、画面はとても大きいです。でも、素材はやわらかいので、折りたたんで、ポケットなどに入れられます。以上四つご紹介しましたが、こんな携帯が本当に出来たら、楽しそうですね。"}, {"k": "spk", "s": "女", "t": "いろんなアイディアがあるものね"}, {"k": "spk", "s": "男2", "t": "本当だね。でも、どれも小さくなっていく方向だね"}, {"k": "spk", "s": "女", "t": "そうね。今以上にどこかに置き忘れちゃいそう。この前も喫茶店に忘れてきちゃって、大変だったのよ"}, {"k": "spk", "s": "男2", "t": "そうだったね。君なら、どれがいい~"}, {"k": "spk", "s": "女", "t": "腕に直接付けられるのだったら、安心だから。わたしなら、これね"}, {"k": "spk", "s": "男3", "t": "そうだね。ジョギングの時も便利そうだしね。僕は、画面が大きくて、見やすいのがいいな。字が小さいのはなあ"}, {"k": "q", "t": "質問1女の人はどの携帯が気に入っていますか。解答1"}, {"k": "q", "t": "質問2男の人はどの携帯が気に入っていますか。解答4"}]}], "2011-12": [{"head": "電話で男の学生と引越し会社の人が話しています。", "lines": [{"k": "spk", "s": "男", "t": "あっ、もしもし。あの、ちょっと急なんですが、来週東京から北海道に引っ越したいんです。私、学生なんですが、できるだけ安い引越しの方法ないかなあって思ってるんですが。"}, {"k": "spk", "s": "女", "t": "いくつかプランがございますが、学生さんでしたら、学生パックという割安なプランがございます。ただ、大型家具がある場合には、別料金となります。"}, {"k": "spk", "s": "男", "t": "そうですか。べッドとあと、大きめの本棚が二つあるんで"}, {"k": "spk", "s": "女", "t": "ああ、そうしますと、かえって高くなりますね"}, {"k": "spk", "s": "男", "t": "そうですか。"}, {"k": "spk", "s": "女", "t": "えっと、トラック便というのが、ご利用の多い一般的なプランなんですが、そうですね、お客様の場合、北海道までということで、かなり距離がありますので、料金のほうもそれだけかかってしまうんですね。むしろ、鉄道を利用した鉄道便を利用されたほうがお得になります。ただ、鉄道便ですと、荷物の扱いが若干荒い場合がございますので、壊れやすい電機製品ですとか、楽器などがある場合は、お勧めできないんですが"}, {"k": "spk", "s": "男", "t": "そうですか。"}, {"k": "spk", "s": "女", "t": "それと、ほかに同じトラック輸送でも、「エコノミー便」と申しまして、ほかのお客様のお荷物と一緒に運ばせていただく方法ですね。こちらですと、トラック便に比べて、4割ほどお安くなりますが、お荷物の到着までにお時間をいただきます。"}, {"k": "spk", "s": "男", "t": "へえ、そうですか。何日ぐらいかかるんですか。"}, {"k": "spk", "s": "女", "t": "そうですね。一週間程度でしょうか。同じ方面に運ぶ荷物が集まった時点で出発いたしますので、そのときの状況によって変わってくるんですが"}, {"k": "spk", "s": "男", "t": "そんなにかかるんじゃ、ちょっと困るよなあ。..ううん、家具は多いけど、特別壊れやすいものもないし、じゃあ男の学生はどの方法を選びますか。"}, {"k": "ch", "t": "1.学生パック"}, {"k": "ch", "t": "2.トラック便"}, {"k": "ch", "t": "3.鉄道便"}, {"k": "ch", "t": "4.工コノミー便"}]}, {"head": "大学のゼミで、先生と学生ニ人が卒業研究について話しています。", "lines": [{"k": "spk", "s": "男1", "t": "はい、上田君、発表ありがとう。ええっと、木下さんはどう思いますか"}, {"k": "spk", "s": "女", "t": "そうですね。タイトルの子どもの言葉の獲得についてなんですけど、子どものことばっていうのが、何を指しているのか、はっきりしてないと思いました。日本語のことなのか、外国語のことなのか、なんか聞いててよく分かりませんでした。両方取り上げてるんですよね。"}, {"k": "spk", "s": "男2", "t": "はい、メインは外国語のことだったんですけど、調べてるうちに日本語のことにも広がっちゃって"}, {"k": "spk", "s": "男1", "t": "うん、ちょっとあいまいでしたね。テーマを絞り込むか、または章を増やして両方ともしっかりまとめるか"}, {"k": "spk", "s": "男2", "t": "そうですね。もともとは、メインテーマは一つのつもりだったので、その方向でまとめてみます。"}, {"k": "spk", "s": "女", "t": "そうすれば、子どもの言葉というのが何を指すか、はっきりすると思います。"}, {"k": "spk", "s": "男1", "t": "そうですね。じゃ、そんな感じでちょっと考え直してみて。そうしたら、研究の目的とも合ってくるんじゃないかなあ。"}, {"k": "spk", "s": "男2", "t": "はい、そうします。男の学生は、卒業研究をどのように修正することにしましたか。"}, {"k": "ch", "t": "1.タイトルを変更する"}, {"k": "ch", "t": "2.テーマを絞る。"}, {"k": "ch", "t": "3.章を増やす。"}, {"k": "ch", "t": "4.研究の目的を変更する。"}]}, {"head": "イベント会場で、アナウンスを聞いたあと、男の人と女の人が話しています。", "lines": [{"k": "text", "t": "アナウンス:皆様、本日はご来場ありがとうございます。午前十時現在の各館の混雑状況と催しもののお知らせをいたします。まず、ロボット館はただいま、一時間待ちとなっております。ロボット館のレストランではロボットがランチをお席までお運びするサービスをしております。お昼近くになりますと、さらに混雑が見込まれます。次に、未来館は現在すぐにお入りいただけます。なお、未来館では一時と三時に映画上映がございます。それから、化石館は現在5分程度の待ち時間でお入りになれますが、11時から恐竜ショウがございますので、そろそろ混雑が始まることが予想されます。また、歴史館の待ち時間は30分程度となっております。歴史館は会場が広いため、見学にお時間がかかります。余裕を持っておいでください。"}, {"k": "spk", "s": "男", "t": "結構込んでるね。効率的に見ないと、全館回れないよ。どこからみる~"}, {"k": "spk", "s": "女", "t": "映画は絶対に見逃せないから、時間に遅れないようにしようね。"}, {"k": "spk", "s": "男", "t": "ふん、分かった、分かった。じゃあ、それまで、どうする~レストランに行く~面白そうだし。"}, {"k": "spk", "s": "女", "t": "並んでる時間がもったいないよ。きっと、お昼すぎたら、空くんじゃない?食べるのは遅くなってもいいよ。ええっと、恐竜ショウも今から一時間後か"}, {"k": "spk", "s": "男", "t": "でも、今ならあまり待たないで入れるし、ショウ以外に見るものもあるんだから。もうすぐ込んできそうだし、その前に行って見ちゃおうよ。ショウは無理して見なくてもいいし。"}, {"k": "spk", "s": "女", "t": "そうだね。じゃ、その後は映画ね"}, {"k": "q", "t": "質問1ニ人はますどこに行きますか。3"}, {"k": "q", "t": "質問2女の人が行きたいところはどこですか。2"}]}], "2012-07": [{"head": "ペットショップで女の人が店員と話しています。", "lines": [{"k": "spk", "s": "女", "t": "あのう、小型犬のメスを探しているんですけど。"}, {"k": "spk", "s": "店員", "t": "どんな犬をお考えですか。"}, {"k": "spk", "s": "女", "t": "初めてかうので、躾がしやすい方が"}, {"k": "spk", "s": "店員", "t": "ご家族は留守がちですか。"}, {"k": "spk", "s": "女", "t": "いいえ、小さい子がいますので、私は大体家にいます。"}, {"k": "spk", "s": "店員", "t": "ええと、最近売れてる小型犬はこの茶色の犬ですね、これはメスですが、おとなしく留守番できます。ただちょっとわがままなので、躾は簡単とは言えませんね。それから、この白いのは中型犬なんですが、メスで賢いので、何でもすぐ覚えますよ。ただ寂しがりゃなので、一人にしないほうがいいですね。"}, {"k": "spk", "s": "女", "t": "あ、そうですか。"}, {"k": "spk", "s": "店員", "t": "それから、この黒いのは小型犬のメスです。基本のしつけはしてあります。ただ噛む癖があるので、小さいお子さんがいると、無理ですかね。グレーのはオスなんですが、躾はしやすいです。お子さんに飛びつくこともありませんよ。"}, {"k": "spk", "s": "女", "t": "やつばり人気があるだけあって、この子犬可愛いわれ躾はちょっと頑張ってみようかな。"}, {"k": "q", "t": "女の人が気に入った子犬はどれですか。"}, {"k": "ch", "t": "1.茶色の犬"}, {"k": "ch", "t": "2.白い犬"}, {"k": "ch", "t": "3.黒い犬"}, {"k": "ch", "t": "4.グレーの犬"}]}, {"head": "車の店で、店員と夫婦が話しています。", "lines": [{"k": "spk", "s": "店員", "t": "お客様、気になるお車、おありでしょうか"}, {"k": "spk", "s": "女", "t": "んえ、これ、スターティア、ただ、ちょっとドアの数のことで悩んでるんです"}, {"k": "spk", "s": "店員", "t": "スターティアにはドアが二つのタイプと四つのタイプがございます。ツードアの方が、フォードアより少々お安くなっております、中の広さは同じなんですがね。"}, {"k": "spk", "s": "男", "t": "うん、ドアは四つあったほうが乗り降りが楽だよな。みんなが遊びに来た時とか"}, {"k": "spk", "s": "女", "t": "でも、子供たちも休みの時しか来ないし、普段乗るのは私たち一人だけでしょう~少しでも安い方がいいじゃない。"}, {"k": "spk", "s": "男", "t": "そうだね、あ、確かこちらでは新車と中古車両方扱ってるんでよね"}, {"k": "spk", "s": "店員", "t": "はい、どちらも販売しております。男.平日はほとんど乗らないから、新車じゃなくてもいいかなっていう感じですけどね。"}, {"k": "spk", "s": "女", "t": "でも、やつばり新車の方が保証も性能も信頼できるんでしよ。"}, {"k": "spk", "s": "店員", "t": "いや、うちで扱っている中古車は整備をしつかりしておりますので、その点は自信を持っておすすめできますよ。"}, {"k": "spk", "s": "男", "t": "ほら、大丈夫だって"}, {"k": "spk", "s": "店員", "t": "ただ、今環境に配慮した新車は大幅な減税がありまして、スターティアはその対象になっておりますので、お求めいただきやすくなっております。それでも、やつばり、まあ、中古車の方が若干お安くなっておりまして、中古車でしたら、フォードアでも、新車のツードアと同じぐらいお値段でご購入いただけます。"}, {"k": "spk", "s": "女", "t": "あ、そうなの~だったら、子供達来たとき便利な方がいいわね。"}, {"k": "spk", "s": "男", "t": "だろう~"}, {"k": "spk", "s": "女", "t": "運転するのはあなただしね。あなたの言う通りでいいわ。"}, {"k": "q", "t": "夫婦はどんなクルマを買いますか?"}, {"k": "text", "t": "1ドアが二つの中古車の2ドアが二つの新車3ドアが四つの中古車4ドアが四つの新車"}]}, {"head": "テレビで男の人がロボットについて話しています。", "lines": [{"k": "spk", "s": "男", "t": "今日は敬老の日ですね。数老の日にちなんで、おじいちゃん、おばあちゃんに贈りたい夢のロボットというテーマで、小学生に絵を描いてもらいました。その中から四つこ紹介したいと思います。まず、一番はネコ型の掃除ロボットです。復雅に部屋の中を歩き回ったり、階段をのぼったり下りたりしながら、掃除してくれます。二番は窓を拭く口ポットこちらは魚の形をしています。上下にゆっくり移動しながら、窓を拭いていきます水族館で魚を眺めているような気持ちになってもらいたいとのことです。三番はズボン型、一見トレーニング用のズボンですが、なかに仕掛けがしてあって、弱くなった足腰をサポートしてくれます。雨に濡れても大丈夫です。四番は鳥の型。話し相手になってくれ、何か緊な場合には、などに通する機能が付いています"}, {"k": "spk", "s": "女の子", "t": "え~、面白いね。おじいちゃんにあげるんだったら、何がいいかな"}, {"k": "spk", "s": "男の子", "t": "うん、おじいちゃん、最近足が痛いってよく言ってるよね。毎日散歩してるけど。"}, {"k": "spk", "s": "女の子", "t": "うーん、近所に坂多いもんね。足のサポートをしてくれるのがいいかもね。"}, {"k": "spk", "s": "男の子", "t": "そうだね。おばあちゃんは猫好きだから。"}, {"k": "spk", "s": "女の子", "t": "え~でも、この間、おばあちゃんが高いところの窓を拭いているのを見て、危ないなって思ったんだ"}, {"k": "spk", "s": "男の子", "t": "そうか。椅子の上にのるのって危ないもんね。じゃ、おばあちゃんのかわりにやってくれるロホットをあげたいね"}, {"k": "q", "t": "質問1:ニ人はおじいさんにはどのロボットがいいと言っていますか。3"}, {"k": "spk", "s": "質間2", "t": "ニ人はおばあさんにはどのロボットがいいと言っていますか。2"}]}], "2012-12": [{"head": "園芸店で女の人と店の人が話しています。", "lines": [{"k": "spk", "s": "女", "t": "あのう、すみません。庭に花を植えたいんです。明るい色の。でも、どれがいいかわからなくて初心者なんで、手入れが簡単なものがいいんですけど。"}, {"k": "spk", "s": "男", "t": "なるほど"}, {"k": "spk", "s": "女", "t": "ああ、それと、せつかく植えるなら、なるべく長い間花が楽しめるものがいいんですけど。"}, {"k": "spk", "s": "男", "t": "それでしたら、こちらの花のカタログご覧ください。この一番の花、これは一年中赤やピンクの色やかな花が咲きますよ。ただ虫がつきやすいんで、まめに面倒を見てやんなきゃなんないんですけどねえ。手入れが楽っていうのは、あっ、この二番の花。これはほっといてもめったに枯れたりしませんね。春の二週間ほどですが、いろんな色の花が楽しめますよ。"}, {"k": "spk", "s": "女", "t": "うーん、花が咲くなら木でもいいかなと思ってるんですけど、背が低いものだったら。"}, {"k": "spk", "s": "男", "t": "そうですか。でしたら、こちらの二番はいかがですか。腰ぐらいの高さにしかならない木で、切っていっても葉っぱは落ちないので、手がかかりませんよ。濃いピンクの花が年間通して楽しめます。あっ、この四番の花もお勧めです。これも木なんで、一度植えたら、植え替える必要もないですし、ほとんど虫がつくこともないですよ。まあ、これは先ほどの三番の花にも言えることなんですけどね。四番の花は白で、春から夏にかけて楽しめます。葉っぱは秋から冬に全部落ちれてしまいますけどね"}, {"k": "spk", "s": "女", "t": "どれにしよう。難しいな。手入れが大変なのはやつばり無理だし、葉っぱが落ちちゃうのも掃が面倒だしなあ、後花が長く咲いてるの、となると、これかな~これください!"}, {"k": "spk", "s": "男", "t": "ありがとうございます"}, {"k": "q", "t": "問い女の人はどの花を買いますか。"}, {"k": "text", "t": "1一番の花2二番の花3三番の花。4四番の花"}]}, {"head": "会社で、男の上司とニ人の社員が話しています", "lines": [{"k": "spk", "s": "男1", "t": "ああ、会社の宣伝用ポスター新しくする件だけど。"}, {"k": "spk", "s": "男2", "t": "はい。"}, {"k": "spk", "s": "男1", "t": "そろそろどこに作ってもらうか決めたいんだけど。検討進んでる?"}, {"k": "spk", "s": "男2", "t": "はい。今のところ、前回お願いしたとこと、先日サンプルをもらった新しいとこの二社に見積もりを取っていて。これが見積もりです。"}, {"k": "spk", "s": "男1", "t": "どれ?うーん。これだと、新しいところのほうがだいぶ高いね"}, {"k": "spk", "s": "女", "t": "そんなんです。私は前回のところがいいじゃないかなって思ってるんですけど、お互いやり方もわかってますし。"}, {"k": "spk", "s": "男2", "t": "でも、前回のは、デサインがあんまり面白くなかったし、僕としては新しいほうにお願いして、嶄嶄なイメージを出したいんですけど。"}, {"k": "spk", "s": "男1", "t": "うん、確かにこの間もらったサンプル、籍朝よかったなあ。"}, {"k": "spk", "s": "男2", "t": "はい。予算のことはまだ話し合いの余地があると思いますし。"}, {"k": "spk", "s": "女", "t": "確かにデザイン面ではこっちのほうがいいんですけど。でも値下げに応じてくれるかどうか。"}, {"k": "spk", "s": "男1", "t": "わかった。じゃあ、とりあえすそこにかけあってみてくれる?それで、下げてもらえるようなら、依頼する方向で"}, {"k": "spk", "s": "男2", "t": "わかりました。連絡とってみます。"}, {"k": "q", "t": "問いポスターについて、これからますどうすることになりましたか。"}, {"k": "text", "t": "1前回の会社からサンプルをもらう。2前回の会社から見積もりをもらう。3新規の会社と価格を交渉する4新規の会社に製作を依頼する。"}]}, {"head": "ラジオを聴きながら、女の人と男の人が話しています。", "lines": [{"k": "spk", "s": "ラジオ", "t": "今日は秋の夜長にお勧めの本四冊をご紹介します。まずは昨年の文学を﨎した「りん'四十代女性編集者と三十代フリーターの男性、そして二十代の女子学生が三人で一軒を借りて暮らすというストーリーです。世代の違う三人の交流を丁寧に描いています。続いて「秋の日」、一人暮らしの老人が訪問ボランティアで来る若者に自分の人生を語るうちに、互いの孤独から解されていく話です。二冊目は「分かれ道」。日本の金融業界を巡るサスペンスですが、同時に主人公の成長も描かれています。最後は「金魚」。そばやの主人の目を通して、江戸の文化が開花した時代の人々の様子を生き生きと描いた作品です。"}, {"k": "spk", "s": "女", "t": "これ、私はもう全部読んじゃった。老人の話が一番面白かったなあ。"}, {"k": "spk", "s": "男", "t": "僕もどれか読んでみようかなあ"}, {"k": "spk", "s": "女", "t": "銀行の話なんかがいいんじゃない。"}, {"k": "spk", "s": "男", "t": "うーん、うちに帰ってまで仕事のことなんか考えたくないよ。"}, {"k": "spk", "s": "女", "t": "そうか、サスペンスだから好きだと思うんだけど。ええと、後は時代小説はあまり読まないでしょう。けっこうおもしろいけど"}, {"k": "spk", "s": "男", "t": "そうだね。どっちかっていうと、現代もののほうがいいかな。うーん、老人の話がいいかな。ね、三人の共同生活の話って恋愛ものなの?"}, {"k": "spk", "s": "女", "t": "いや、そうなりそうになるんだけど、ならないんだよね。そこがおもしろいかなっと。"}, {"k": "spk", "s": "男", "t": "そうか。じゃ、そっちを先に読もうかな"}, {"k": "q", "t": "質問1女の人はどの本が一番面白いと思いましたか。(正解:2)"}, {"k": "q", "t": "質問2男の人はどの本を最初に読むことにしましたか。(正解:1)"}]}], "2013-07": [{"head": "電気店で、女の人と店員が話しています。", "lines": [{"k": "spk", "s": "女", "t": "あのう、巓型のテレビを買いたいと思ってるんですけど・・"}, {"k": "spk", "s": "男", "t": "どのようなものをお探しですか。"}, {"k": "spk", "s": "女", "t": "占然や美術番組をいい画質で見たいんです。それからわたし、機械が苦手なので、操作はできるだけ簡単なほうがいいんです。"}, {"k": "spk", "s": "男", "t": "そうですか。今一番売れているのはこちらの一番です。このタイプのものでは、画質のよさが際立ってますね。操作は少し複雑ですが、分からないことはサポートセンターが24時間対応していますからいつでも聞いてください。"}, {"k": "spk", "s": "女", "t": "はい。"}, {"k": "spk", "s": "男", "t": "それから、二番の商品は色がくっきりとしているのが徴です。スピーカも高性能で、臨場感たつぶりです。操作はそれほど難しくはありませんよ。"}, {"k": "spk", "s": "女", "t": "はあ。"}, {"k": "spk", "s": "男", "t": "それから、この三番は壁にかけるタイプです。画面の色の自然さが好評です。操作性はこれが一番でしょう。"}, {"k": "spk", "s": "女", "t": "そうですか。"}, {"k": "spk", "s": "男", "t": "それから、こちらの四番は当店がおすすめしている商品です。眼鏡をかけると立体映像が楽しめます。操作は簡単モードと普通モードの切り替えができるので、機械が苦手な方でも大丈夫です。"}, {"k": "spk", "s": "女", "t": "なるほど。画質がいいのは魅力だけど、分からなくなるたびに電話っていうのもね...壁にかけるタイプもいいけれど、アパートだから金具をつけるわけにもいかないし、まだ立体映像までは必要ないわね。音は考えてなかったけれど、臨場感があってよさそうね。れにします。女の人はどのテレビを買うことにしましたか。"}, {"k": "ch", "t": "1.一番のテレビ"}, {"k": "ch", "t": "2.二番のテレビ"}, {"k": "ch", "t": "3.二番のテレビ"}, {"k": "ch", "t": "4.四番のテレビ"}]}, {"head": "社員ニ人と上司が会社説明会について話しています。", "lines": [{"k": "spk", "s": "男1", "t": "部長、来月一日に予定している会社説明会なんですが、参加希望者が予想をかなり上回りそうなんです。"}, {"k": "spk", "s": "男2", "t": "そう。大勢来てくれるのはいいけど、会場は大丈夫なの~"}, {"k": "spk", "s": "男1", "t": "今予約してあるホテルの会場では入りきらないかもしれないんです。また別の日に二回目の説明会を開いたほうがいいかと思うんですが、"}, {"k": "spk", "s": "男2", "t": "いや、別の日となると、都合がつかなくなる人も多くなるだろうから、説明会の日取りは動かさないほうがいいね"}, {"k": "spk", "s": "女", "t": "あ、説明会は午前を予定しているんですが、さきほどホテルに聞いてみたところ、午後も同じ会場を使えるそうです。"}, {"k": "spk", "s": "男1", "t": "じゃ、午前と午後の二回にしましょうか。それなら、スタッフを増やす必要もないですし。"}, {"k": "spk", "s": "女", "t": "念のため、他の部屋についても聞いてみたんですが、小さめの部屋も空いているそうですたとえば、説明会は予定通り午前中だけにして、会場を二つにするってこともできますよね。"}, {"k": "spk", "s": "男1", "t": "ん~会場を分けるとなると、人だけじゃなく、機も増やさなくちゃいけませんよね。"}, {"k": "spk", "s": "女", "t": "あと、大宴会場も使えるって言ってましたよ。ここなら全員入れます。"}, {"k": "spk", "s": "男1", "t": "それでも、やつばり人を増やさなくちゃいけませんよね。"}, {"k": "spk", "s": "男2", "t": "そうだな。スタッフは増やさず、説明会の回数を増やすのが現実的だなその方向で、会場を確保しておいてください。会社説明会をどのように行うことになりましたか。"}, {"k": "ch", "t": "1.別の日にもう一度する。"}, {"k": "ch", "t": "2.同じ日の午前と午後にする。"}, {"k": "ch", "t": "3.同じ日の同じ時間に一つの会場でする。"}, {"k": "ch", "t": "4.同じ日の同じ時間に二つの会場でする。"}]}, {"head": "テレビの通販番組で時計について説明しています。", "lines": [{"k": "text", "t": "今日は高級腕蒔計四点のご案内です。まずは、商品番号一番。人気の高い定番商品です。全体に宝石をちりばめ、とても篳やかで、ベルトをかえればビジネス、プライベート両方にお使えいただけます。次、商品番号一番は海のスポーツにもつれていけるタフな一品。防水効果が非常に高く、深さ100メートルの水中でもまったく問題ありません。そして、商品番号二番は二つの時刻を示せるのが特長です。海外旅行にお出かけの際、現地と日本の時間を同時に確認でき、便利です。そして最後、商品番号四番は1962年の発売当時のままのデサインです。この時計は一日一回ねじをまかなければなりませんが、手間をかけることで愛着も湧き、一生を付き合える一品です。以上四点、すべて男性用、女性用をご用意しております。"}, {"k": "spk", "s": "男", "t": "新しい時計ほしいって言ってたよね。君は海外出張多いから、二つの国の時間が分かるのを便利なんじゃない~"}, {"k": "spk", "s": "女", "t": "うん、確かにそうなんだけど。デザインがいまひとつかな。それより、この宝石のついている時計、友達が持っているんだけど、ベルト換えると雰囲気が全然違って見えるの・・・。ね、あたしこれにする。あなたもペアで持たない~"}, {"k": "spk", "s": "男", "t": "ん~君には似合うと思うけど、僕にはね、ちょっと派手すぎるかな。僕はよく海に行くし、これなら海でもてきるよね。"}, {"k": "spk", "s": "女", "t": "そうね。でも、高価な時計を海でするなんて、ちょっともったいないんじゃない~それに仕事でも使うんだったら、もう少し落ち着いたテサインのもののほうがいいと思うけど。"}, {"k": "spk", "s": "男", "t": "そうだよね。実は一番気になってたのはアンティークみたいなのなんだ。僕も思い切って新しくしちゃうかな。"}, {"k": "spk", "s": "女", "t": "いいんじゃなも普通の人だと毎日ねじをまくのは愉くさがるだろうけど、あなた、朝まめだものね。"}, {"k": "q", "t": "質問1女の人が・買おうと思っているのはどれですか。(正解:1)"}, {"k": "q", "t": "質問2男の人が'買おうと思っているのはどれですか。(正解:4)"}]}], "2013-12": [{"head": "インターネットでホテルの求人情報を見ながら男の学生と女の学生が話しています。", "lines": [{"k": "spk", "s": "男", "t": "ねえ、ホテルでアルバイトしたいって言ってなかったつけ。"}, {"k": "spk", "s": "女", "t": "うん。将来ホテルに就職したくて学生のうちに接客を学んでおきたいんた"}, {"k": "spk", "s": "男", "t": "朝日屋ホテルの求人情報、いろいろ出てるよ。うちから近くていいんじゃない~:女二/\\え~"}, {"k": "spk", "s": "男", "t": "いろんな職種の募集が出てて、時間も時給もいろいろだけど。接客業がいいんだよね。"}, {"k": "spk", "s": "女", "t": "うん。火曜と日曜しかアルバイトできないんだけど、週二日までで時給千円以上の仕事なんてある~"}, {"k": "spk", "s": "男", "t": "あっ、ほら、ウェディング部門の桶助これは時給千二百円で、週二日か三日勤務だって、土曜か日曜に入れる人、歓迎だって書いてある。結婚式の企画を手伝うみたいだよ。えーと、それから夜間のフロント業務は時給千五百円だよ。週二日以上勤務できる方って書いてある勤務は夜9時から翌朝6時までだけど。チェックインや電話応対の仕事をするんだって。"}, {"k": "spk", "s": "女", "t": "う~ん。どっちも面白そうだね。"}, {"k": "spk", "s": "男", "t": "あっ、レストランでの接客務も時給千二百円だよ。週三日以上って書いてあるけど。"}, {"k": "spk", "s": "女", "t": "そういえば、最近、このホテルのシェフが世界的な料理コンクールで入賞してたよ。"}, {"k": "spk", "s": "男", "t": "へえ、すごいんだね。あとは、ロビーのサービス業務も募集してるよ。時給八百五十円で週に二日だって。ロビーでお客を案内したりクロークで接客したりする仕事だね。"}, {"k": "spk", "s": "女", "t": "うーん。時給は大切だし、徹夜の仕事は避けたいし、勤務日にも無理がなさそうな、これに応募しよう。"}, {"k": "q", "t": "女の学生はどの仕事に応募しますか。"}, {"k": "ch", "t": "1.ウェディング部門の補助"}, {"k": "ch", "t": "2.フロントでの受付"}, {"k": "ch", "t": "3.レストランでの接客"}, {"k": "ch", "t": "4.ロビーでの接客"}]}, {"head": "レストランの経営者と社員ニ人が店の経営について話しています。", "lines": [{"k": "spk", "s": "男1", "t": "最近店の売り上げが減ってるんだよね。特に、ランチタイムやそのあとからディナーまでの午後の時間帯の売り上げ、伸び悩んでるんだよね。どうしたものかな。"}, {"k": "spk", "s": "女", "t": "ランチタイム、食べ放題にするとかどうですか。最近、人気あるみたいですよ。食べ放題"}, {"k": "spk", "s": "男1", "t": "うーん。食べ放題用の新しいメニュー開発とか準備に手間がかかりそうだね。"}, {"k": "spk", "s": "男2", "t": "あのう、冗~り上げを伸ばすことを考えるよりも経竇節籤を考えたほうがいいんじゃないんでしょうか。例えば、お客さんの少ないランチのあとの時間、思い切ってお店をしめるっていうのはどうですか。"}, {"k": "spk", "s": "男1", "t": "確かに経費は節減できるけど。"}, {"k": "spk", "s": "女", "t": "それよりもその時間に人気メニューを格安で提供してお客さんを集めるっていう方法もありますが"}, {"k": "spk", "s": "男1", "t": "店の味を少しでも多くの人に知ってもらえる可能性はあるな。店をしめるよりは前向きな方法だし。"}, {"k": "spk", "s": "男2", "t": "あと、オーダーを取る業務を機械化して、人件費を削るというのはどうでしょうか。"}, {"k": "spk", "s": "男1", "t": "それは初期費用がかかるよ。費用はあまりかけられないし、かといって、頑張ってくれてるスタッフの減給は考えられないし。となると、今回はさっきの前向きな案でいこう。レストランでは何をすることになりましたか。"}, {"k": "ch", "t": "1.ランチタイムに食べ放題を導入する。"}, {"k": "ch", "t": "2.客の少ない時間帯の営業をやめる"}, {"k": "ch", "t": "3.午後の時間帯に人気メニューを割引する。"}, {"k": "ch", "t": "4.オーダーを取る業務を機械化する。"}]}, {"head": "大学のオリエンテーションで先生が新設されるゼミナールについて説明しています。", "lines": [{"k": "spk", "s": "女1", "t": "来年度二年生を対象に新設される基礎ゼミナール1から4について説明します。まず、基礎ゼミナール1は国内外を問わず異なる文化背景を持った人とのコミュニケーション上の問題をいろいろ取り上げて考えるゼミです。基礎ゼミナール2では国際開発協の基礎理論を学ぶと同時に現地での研修も予定しています。将来NGOで働いてみたいと思っている学生にはうってつけの内容ですね。基礎ゼミナール3は日本の歴史を外交という外国との関係から見直していくゼミです。基礎ゼミナール4は他学部で開かれているゼミですが、当学部の単位として認めるものです。内容は、英語のロ語表現を朝遙葯に分析するものです。英語の言語構造に興味がある人にお勧めです。ただし、英語の基礎が出来ていない人には大変なので、その点注意してください。"}, {"k": "spk", "s": "女2", "t": "面白そうなゼミが四つできるのね。せつかくだから、この中から一つ取ろおっと。山中君は~"}, {"k": "spk", "s": "男", "t": "うん、僕も。僕は英語を使いこなせるようになりたいって思ってるんだけど。"}, {"k": "spk", "s": "女2", "t": "じゃあ、ロ語表現のがいいんじゃない~英語は得意でしょう~"}, {"k": "spk", "s": "男", "t": "まあね。でも、英語話してると、こっちの意図とは異なって解釈されて戸惑うことがあるんだよね。今の説明を聞いて、それって単に語学能力だけの問題じゃなくて、育った環境とか文化とかいろんなことが影響しているのかもしれないと思って、その辺をしつかり学べそうだからこれ取ろう。"}, {"k": "spk", "s": "女2", "t": "うん、ちょうどいいね、わたしは国際関係に興味があって、将来は海外で働きたいと思っているから。それに役立つのがいいんだけど"}, {"k": "spk", "s": "男", "t": "だったら、この現地で研修できるっていうのがびったりだね"}, {"k": "spk", "s": "女", "t": "うん。いずれはそういうことも勉強する必要があるけど。まずは、日本がほかの国とどのような関係を築いてきたのか、その点を学びたいと思っているんだ。だから、このゼミにする"}, {"k": "spk", "s": "男", "t": "そうか。"}, {"k": "q", "t": "質問1:男の学生はどのゼミナールを選びますか。1"}, {"k": "q", "t": "質問2:女の学生はどのゼミナールを選びますか。3"}]}], "2014-07": [{"head": "市役所で男の人と係りの人が話しています。", "lines": [{"k": "spk", "s": "男", "t": "あのう、市が開催している文化教室に参加したいと思ってるんですが。"}, {"k": "spk", "s": "女", "t": "どのような分野にこ興味がおありですか。"}, {"k": "spk", "s": "男", "t": "この地域の歴史や文化を学べるようなのがいいかと思って。"}, {"k": "spk", "s": "女", "t": "そうですか、いくつかありますが、ご希望の曜日や時間帯はありますか"}, {"k": "spk", "s": "男", "t": "仕事から帰るのが平日は夜七時以降になりますね。週末は基本的に参加できます。月に1、2回ぐらいのものがいいですね"}, {"k": "spk", "s": "女", "t": "では、こちらの一覧をご覧ください。昔の暮らしを学ぶ会というのがありますが、この土地の古い文献を読んで昔の暮らしを学ぶ活動です。月に2回やってます。あ、これ、水曜の6時からですね。それから祭り保存会っていうのが7時からあります。月に2回、金曜日に集って、このあたりに伝わる祭りの由来について勉強したり、踊りを練習したりします。毎年、まつりの時は、保存会の皆さんが踊ってくださるんです"}, {"k": "spk", "s": "男", "t": "んえ、楽しそうですね"}, {"k": "spk", "s": "女", "t": "週末ですと、土曜日の午後に歴史名所クラブがありますね。歴史上の名所や史料館などを見学します。こちらは月に1回です。そのほかに、民話に親しむ会というのがあって日曜の午前中に毎週やっていますよ。こは3ヶ月に1回、一泊二日で民話に出てくる土地を、一泊2日で民話に出てくる土地を訪ねる旅行をしています。"}, {"k": "spk", "s": "男", "t": "どれも面白そうですね。でも、遅刻はしたくないし、体を動かすのはすきだけど、人前で踊るのは恥ずかしいし、とまるのもちょっとなあ。そうすると、これですね。"}, {"k": "q", "t": "男の人はどの活動に参加しますか。"}, {"k": "ch", "t": "1.昔の暮らしを学ぶ会"}, {"k": "ch", "t": "2.祭り保存会"}, {"k": "ch", "t": "3.歴史名所クラブ"}, {"k": "ch", "t": "4.民話に親しむ会"}]}, {"head": "経営学研究会の会長と担当者ニ人が講演会について話しています。", "lines": [{"k": "spk", "s": "女1", "t": "再来月開催する講演会ですが、講演を願いしようと思っていた山田先生、その時期は海外へ調査に出かけられるそうなんです。どうしましょうね。"}, {"k": "spk", "s": "男", "t": "ええ、山田先生は経営学の分野では第一人者ですし、会員からもお話を伺いたいという声が多いんですよ。日程を変更してもう一度お願いするということはできないんでしょうか。"}, {"k": "spk", "s": "女1", "t": "でも、これから、別の日程で会場を抑えるのは無理です。"}, {"k": "spk", "s": "女2", "t": "そうですね。"}, {"k": "spk", "s": "男", "t": "じゃ、異例ですけど、事前に講演を録画して当日会場で上演するというのではどうでしょう。"}, {"k": "spk", "s": "女1", "t": "うんん、講演は一方通行じゃなくて、参加者と質疑ができる形にしたいわね。"}, {"k": "spk", "s": "男", "t": "じゃ、山田先生に同じ分野の響名な方をどなたかご紹介いただいたらどうでしょう。"}, {"k": "spk", "s": "女1", "t": "それなら、一層のこと、違う分野の大家にお願いしてはどうでしょうか。例えば、環境学の先生をお呼びするとか"}, {"k": "spk", "s": "男", "t": "それはいくらなんでも飛躍しすぎでしょう"}, {"k": "spk", "s": "女2", "t": "まあ、違う分野との連携も大切だと思いますけど、それは今後の課題として、今回は山田先生にご相談しましょう講演会はどうすることにしましたか。"}, {"k": "ch", "t": "1.講演会の日を変更する"}, {"k": "ch", "t": "2.山田先生に講演を録画してもらう"}, {"k": "ch", "t": "3.山田先生に講演者を紹介してもらう"}, {"k": "ch", "t": "4.関連分野の人に講演を依頼する"}]}, {"head": "テレビの旅行番組で観光コースを紹介しています。", "lines": [{"k": "text", "t": "アナウンス:えー、今日は山中町て今人気の観光コースを四つご紹介します。コース1は山中町のシンポルとして親しまれている登山電車で、文字通り山の急斜面をのぼります。来週半ばごろから、ちょうど山のさくらが満開となりますから、お勧めです。コース2は、暴気て走る汽車て、山中町と隣町の間を往復するツアーです。今はなかなか見る機会がない蒸気機関車ですが。煙を吐きながらカ強く走る姿が大変人気です。コース3は、ロープウェーで山を越えて湖へおりていきます。山中町の谷の間をのぼり山頂を越えると、目の前に突然湖の景色が広がります。コース4は、船で湖を一周します。船に乗って湖から山中町の雄大な山並みをゆったり楽しむことができます。"}, {"k": "spk", "s": "女", "t": "山中町ってちょうど来週の三連休に二泊三日で私たちが行くとこでしょう。いろいろ楽しめそうね。私、空中から谷や湖を見下ろすっていうの、興味あるなあ。"}, {"k": "spk", "s": "男", "t": "うん、でも、高いとこ苦手なの忘れてた。できれば湖から山を眺めるってほうにしたいけど、どう"}, {"k": "spk", "s": "女", "t": "そっか、咼いところ、苦手なのは忘れてたでも、確かに天気がよければ水面に山が映ってきれいかもしれないね"}, {"k": "spk", "s": "男", "t": "じゃ、旅行の二日目に乗ろうよ。初日は着くのがタ方になるから、移動だけだし、天気予報によると、一日目までは晴れるらしいから、きっと楽しめるよ。二日目からは天気が悪くなるんだって"}, {"k": "spk", "s": "女", "t": "そうなんだ。でも、電車なら大雨じゃないかぎり、止まらないよね、山中のシンポルははずせないよ。"}, {"k": "spk", "s": "男", "t": "うん、桜も見たいし、機関車は乗ったことがあるから、今回はいいよね。問題1ニ人は旅行のニ日目どのコースを選びますか。解答4問題2ニ人は旅行の三日目どのコースを選びますか。解答1"}]}], "2014-12": [{"head": "ペットショップで女の人と店員が小鳥について話しています。", "lines": [{"k": "spk", "s": "女", "t": "すみません、小鳥を飼いたいんですけど・・"}, {"k": "spk", "s": "男", "t": "どんな鳥がよろしいですか。"}, {"k": "spk", "s": "女", "t": "初めてなんで、飼いやすいのがいいです。鳴き声がきれいなのがいいですね。"}, {"k": "spk", "s": "男", "t": ""}, {"k": "spk", "s": "女", "t": "それと、人によくなっくのがいいんですが..こう当ヾしんおうせい"}, {"k": "spk", "s": "男", "t": "よくなっくのはこの赤い鳥で、好可心旺盛で遊び好きですよ。気を引こうと擦り寄ってくるしぐさが愛らしいんです。あ、でも寒さに敏感で、飼育しやすいわけじゃないんですけどね。"}, {"k": "spk", "s": "女", "t": "温度管理が必要ってことですか。"}, {"k": "spk", "s": "男", "t": "はい、その点がご心配なら、この白い鳥はいかがですか。気温の変化に比較的強くて、戒心が強い鳥ですけど。一週間もするとなついてくれますよ。それに、澄んだ声で囀りますこの黄色い鳥も寒さに強いですよ。かさに乗ってきて愛たつぶりなんですよ、日中にぎやかにしています。"}, {"k": "spk", "s": "女", "t": "確かにかわいいらしいけど、一日中鳴いているっていうのは騒がしいし、ちょっと.."}, {"k": "spk", "s": "男", "t": "それでは、この水色の鳥、こちらはロ裕を吹くような美しい声で人気です藤病で神経質なので触れ合いはあまり期待できませんが、なによりこの声の美しさがお勧めなんです。"}, {"k": "spk", "s": "女", "t": "そうですか。うーん、なついてくれるほうがいいですね。でも飼いにくいのが大変だし、この鳥にします。"}, {"k": "q", "t": "女の人はどの鳥を飼いますか。"}, {"k": "text", "t": "1赤い鳥2白い鳥3黄色い鳥4水色の鳥"}]}, {"head": "スーパーで店長と店員ニ人が惣菜の販売について話しています。", "lines": [{"k": "spk", "s": "店長", "t": "先週から秋の実りフ=アでキノコを使った惣を販売しているけど、シイタケポールの売り行きが芳しくないようだね。なんか改善する方法はないかな"}, {"k": "spk", "s": "女", "t": "見た目については、肉の団子にシイタケを載せて真ん丸い形にしているので、大きくて見栄えはするんですが、スパイスが少し効きすぎているのかもしれません。常連のお客さんから指摘を受けました"}, {"k": "spk", "s": "店長", "t": "形に関しては串にしたからな、スパイスの風味はうちのスタッフには評判がよかったんだけどね。"}, {"k": "spk", "s": "女", "t": "はい、私たち大人のロには合いますけど。うちは子供連れのお客さんが多いですし。子どもにも喜んでもらえるように、見直してはどうですか。"}, {"k": "spk", "s": "店長", "t": "なるほどね。ほかに気づいた点はないかな"}, {"k": "spk", "s": "男", "t": "試食コーナーで接客に立つ店員の数を増やしたらどうですか。お客さんに試食さえしてもらえれば、必ず売り上げにつながると思うんですが."}, {"k": "spk", "s": "店長", "t": "うーん、すでに試食販売の担当者を一人割り当ててるからね。仕込みや調理の担当者を売り場に回すとなるとね。"}, {"k": "spk", "s": "男", "t": "でしたら、試食コーナーをお客さんの目を引くような楽しい感じに飾りつけてみてはどうでしょうか。"}, {"k": "spk", "s": "店長", "t": "なるほど。それなら飾りつけは子どもが喜ぶようなものにするといいね。じゃ具体案を考えてくれるかな"}, {"k": "spk", "s": "男", "t": "はい。"}, {"k": "spk", "s": "女", "t": "それで、子どものロにも合えば、家族連れのお客さんはきっと喜んで買ってくれると思うんですが."}, {"k": "spk", "s": "店長", "t": "そうだな。それも並行してやっていこう。売り上げを改善するために、何を見なすことにしましたか。"}, {"k": "ch", "t": "1.惣菜の形と販売の担当者数"}, {"k": "ch", "t": "2.惣菜の形と売り場の装飾"}, {"k": "ch", "t": "3.惣菜の味付けと販売の担当者数"}, {"k": "ch", "t": "4.惣菜の味付けと売り場の装飾"}]}, {"head": "テレビでアナウンサーが映画賞の候補作品について話しています。", "lines": [{"k": "text", "t": "アジア映画社曼贇式まてあと一週間候翩作品四つをご紹介します。ーっ目は「手帳」。社会派のリー監督によるドキュメンタリータッチで描かれていた実際の汚職事件がもとになっている作品です。二つ目は「秋の空」、一人の小説家が成功するまでの話を描いたミュージカル、2代トップスターの共演で話題になりました。三つ目は「あの雲」、アクション映画の巨匠ロー監督による、馬と少年との触れ合いを描いた心暖まるドラマて今までとはがらりと異なる作品です。四つ目は「みどりの家」、昨年鮮烈なデビューを飾った佐々木始監督の作品です。ある町で次々に起こる奇な事件に一人の探偵が挑みます。美しい映像と意外な結末が評判です。さて、栄冠を手にするのはどの作品でしょうか。"}, {"k": "spk", "s": "男", "t": "今年の候補は本当にバラエティーに富んでいるよね、どれが賞を取ると思う~"}, {"k": "spk", "s": "女", "t": "そうね。私個人的には動物ものが好きなんだけどね。"}, {"k": "spk", "s": "男", "t": "うーん、今回は新人監督と巨匠の一騎打ちだと思うんだ。迷うところだけど、いくら実力がある監督が撮った作品といっても、新しい分野だし、どうかな。僕は、あの予想を裏切るラストが評判の映画、あれだろうな。映像の美しさが評価されて.."}, {"k": "spk", "s": "女", "t": "そア私は実際にあったあの事件を描いた作品だと思う。現代社会へのメッセージ性があるし。"}, {"k": "spk", "s": "男", "t": "そっか。後、ミュージカルもトップスターが共演してたから、話題性は抜霹たったけど、賞となると話は別かな。観客数はトップで、その一点では大成功を収めたけどね。"}, {"k": "q", "t": "質問1男の人はどの作品が賞を取ると言っていますか。(正解:4)"}, {"k": "q", "t": "質問2女の人はどの作品が賞を取ると言っていますか。(正解:1)"}]}], "2015-07": [{"head": "デバートのカーテン売り場で女の人と店員が話しています。", "lines": [{"k": "spk", "s": "女", "t": "あのう、リビングルームにかけるカーテンを探してるんですけど。"}, {"k": "spk", "s": "店員", "t": "何かご希望がありますか"}, {"k": "spk", "s": "女", "t": "部屋が明るい色の木を使っているので、全体的にナチュラルなイメージで統一できるといいなあと思って。それに、家で洗えるものがいいです。できれば洗濯機て"}, {"k": "spk", "s": "店員", "t": "では、こちらのサンプルをご覧ください。サンプル番号1は天然素材の麻と綿を使用した無地のものです。色はべージュ糸なので、温かみがあります。家で洗っていただけますが、必ず手でお願いします。"}, {"k": "spk", "s": "女", "t": "はい。"}, {"k": "spk", "s": "店員", "t": "それから、こちらのサンプル番号2は、ほかのものより生地が厚手で保温性があります。化學繊維ですから洗濯機でも洗えます。天然素材は変色することがあるんですが、これはその点安心ですし、モダンで大胆な柄がとても人気なんですよ。"}, {"k": "spk", "s": "女", "t": "ええ、斬新ですね。ほかに化学繊維のものは~"}, {"k": "spk", "s": "店員", "t": "そうですね。こちらのサンプル番号3はいグリーンです。柄のないシンプルなタイプですが、生地は2番と同様、しつかりしていて、お部屋を暖かく保ちます。洗濯も2番と同じで家でできます。サンプル番号4は天然集材の染蒋を使って染色したもので、明るい色の木のお部屋にびったりだと思いますよ。洗濯はクリーニングが無難ですね"}, {"k": "spk", "s": "女", "t": "うーん、やつばり無地がいいですね。毎回手洗いやクリーニングというのも大変だし、私は寒がりだから、保温性が高いものがいいわね。このカーテンにします"}, {"k": "q", "t": "問い女の人はどのカーテンを買いますか。"}, {"k": "text", "t": "1サンプル番号1。2サンプル番号2。3サンプル番号3。4サンプル番号4。"}]}, {"head": "中学校で教師3人が夏休みの宿題について話しています。", "lines": [{"k": "spk", "s": "女1", "t": "今日は夏休みに宿題で生徒に読ませる本を決めたいと思います。先週4冊候補をお伝えしましたね。歴史小説、伝記、冒険小説、それと詩集からそれぞれ一冊ずつでしたが、読んてきていただけましたか"}, {"k": "spk", "s": "男", "t": "はい、わたしは伝記がいいと思いました。苦労を重ねながらも幼い頃からの夢を実現した科学者の話中学生にぜひ読んでもらいたいですね。"}, {"k": "spk", "s": "女1", "t": "なるほど、将来を考えはじめる年頃ですからね。この時期の生徒たちには貴重な本ですね。"}, {"k": "spk", "s": "女2", "t": "でも、伝記はちょっと押し付けがましい面があるような気がして、詩集はどうでしょうか。若者の日常生活がモチーフになっていて、中高生の共感を集めていると、いまメディアでも取り上げられてますよね。"}, {"k": "spk", "s": "女1", "t": "そうなんですか。うーん、じゃあ、既に手に取っている生徒も多いかもしれませんよ。"}, {"k": "spk", "s": "女2", "t": "あー、確かにそうですね。では、冒険小説はどうですか。話の展開がはやく、スリルがあって、どんどん先を読みたくなりますし。本を読む楽しみに気づいてもらえるんじゃないかと思うんですけど"}, {"k": "spk", "s": "男", "t": "それは大切なことですね。ただ、内容にちょっと暴力的な描写があるので、その部分をどう考えるか、中には繊な子もいるし、親の反応も気になりますね。その点、伝記なら..."}, {"k": "spk", "s": "女1", "t": "安心ですね。"}, {"k": "spk", "s": "女2", "t": "じゃあ、歴史小説もいいんじゃないでしょうか。ちょうどいま、同じ時代のことを授業であっかっているので、時代背景を知る意味でも、読んでもらいたいですね。"}, {"k": "spk", "s": "女1", "t": "そうですか、それはちょうどいいですね。ちょっと内容が固くても、挑戦してもらいましょう。うーん、夢に向かって歩み始める年頃に「読んでほしいものも捨てがたいし、夏休みの宿題は2冊としましょう。"}, {"k": "q", "t": "問い夏休みの宿題として、どの本を読ませることにしましたか。"}, {"k": "text", "t": "伝2歴史小説と冒険小説。説伝二一口4詩集と冒険小説。"}]}, {"head": "テレビでアナウンサーが農業高校の生徒の取り組みについて話しています。", "lines": [{"k": "spk", "s": "男", "t": "市内の展業高校の生徒の取り組みが地域の活性化に一役買っています。今日は、その一環として生徒が作った食品を四つご紹介します。すべて市内のスーパーなどで買うことができますえー、'ちらの1番は肉を野菜や味噌と一緒に熹詰めた肉味噌です。ハムの製造過程で切り落とされた肉を使っています。しつかりした味で、ご飯との相性も抜群とのことです。この肉はこれまで廃彙分されていましたから、新たな活用の道ができたわけです。2番の食品は地元特産のメロンとこの土地で収穫された米の粉で作ったパンです。米の竇拡夫と地籤展の活性化につながるとメディアでも大きく取り上げられています。3番は地元産のトマトを加工したトマトケチャップです。こちらも規格外のトマトを使っています。かわいいパッケージとラベルは生徒がデサインしたそうですよ。そして4番は最近発売されたサツマイモクッキー。サツマイモの粉で麺を作る鈿土料理にヒントを得て作ったそうです。小麦粉のクッキーより低カロリーで、ミネラル分も多く含まれるとのことです。これから人気が出ることを期待したいですね。"}, {"k": "spk", "s": "女", "t": "へえ、結構本格的にやってるのね。何か買って応援したいなあ。メロンパンなんて美味"}, {"k": "spk", "s": "男2", "t": "そうだね。僕は市場に出回らないものを生かそうとする発想が気に入ったなあ。"}, {"k": "spk", "s": "女", "t": "ああ、あのラベルのデザイン、可愛いかったわね"}, {"k": "spk", "s": "男2", "t": "あっ、僕が言っているのはもうひとつのほう。おかずにしたら、ご飯何倍でも食べられ"}, {"k": "spk", "s": "女", "t": "確かにそうね。わたしは、地元の料理からヒントを得るっていう発想がなかなかだなと思ったわ。あと、地元の特産を二つ組み合わせたアイデアもいいと思うけど、どっちもいいけど、まだマスコミで大きな話題になっていない方を応援しよう。"}, {"k": "q", "t": "質問1男の人はどの食品を気に入ったと言っていますか。(正解:1)"}, {"k": "q", "t": "質問2女の人はどの食品を買って応援したいと言っていますか。(正解:4)"}]}], "2015-12": [{"head": "会社で男の後輩と女の先輩が話しています。", "lines": [{"k": "spk", "s": "男", "t": "先輩、今度海外のお客様がいらっしやるので、接待のアレンジを任されたんです。周りのお客様を気にせずに、ゆっくり話せるどこかいい店、ご存知ないですか。"}, {"k": "spk", "s": "女", "t": "どういう方がいらっしやるの~"}, {"k": "spk", "s": "男", "t": "取引先の営業部長で、日本食がお好きだということです。あと、肉料理が好きなんだそうですが、健康のために、最近は肉はすこし控えているそうです。"}, {"k": "spk", "s": "女", "t": "そうね。和食なら、一つは「小道」っていう魚と野菜料理の店。健康的な食事が楽しめるんじゃないかなこはお客様ごとにそれぞれ別の部屋に通してくれるから、落ち着けるわよ。もうーっは「郷土」という和食の店。こはお肉がおいしくて、看板メニューは和風ステーキなんだけど、実は野菜料理もおいしいの。日本各地の珍しい野菜をたくさん使っているから。お肉を食べなくても楽しめるわよ。この個室もなかなかいいのよ"}, {"k": "spk", "s": "男", "t": "うん、どちらも美味しそうですね。他にもいいところありませんか。"}, {"k": "spk", "s": "女", "t": "「花」っていう創作料理の店。この店のシェフはもともとは洋食が専門だったんだけど、日本料理に転向したんだって。お客様の好みに合わせてコースのメニューを立ててくれるらしいの、部屋は分かれてないんだけど、テープルとテープルの間には仕切りがあるし。"}, {"k": "spk", "s": "男", "t": "ノ、えー"}, {"k": "spk", "s": "女", "t": "あと、中華料理なんだけど「祭り」っていうところもおすすめよ。この店はメニューの種類が多くて、野菜料理も豊富だから、注文に困らないと思うわ。人気の店で、個室は速くうまるから、予約するなら早めにね"}, {"k": "spk", "s": "男", "t": "うーん。せつかく日本に来るんだから、和風がいいですね。でも、控えてるものがあるのにそれが売りの店に連れてくっていうのはちょっと。で、個室があるところと言ったら..早速電話してみます。男の人はどの店に電話することになりましたか。(1)小道。2郷土。(3)花。(4)祭り。"}]}, {"head": "歴史博物館で職員三人が記念イベントについて話しています。", "lines": [{"k": "spk", "s": "男1", "t": "この歴史博物館の開館10年記念イベントのことなんだけどね。市の小中学生に市内にある城や遺跡についてもっと関心を持ってもらえるような企画をたてたいんだ。歴史に興味をもってもらうせつかくの機会だからね。何かいい案はないかな。"}, {"k": "spk", "s": "女", "t": "そうですね。例えば、遺跡を身近に感じてもらうために、古代の人々が身につけていたアクセサリーを実際に作ってみるとか、あるいは中山城でクイズ形式でお城の謎を解きながら、中を探険するツアーをするとか。どちらも歴史になじみがない小中学生にも楽しんでもらえると思います"}, {"k": "spk", "s": "男1", "t": "なるほど。でも、アクセサリーだと男の子、集まるかな。クイズのほうは子供たち喜びそうだね、ゲーム感覚で。ほかにはどう~"}, {"k": "spk", "s": "男2", "t": "そうですね。市内には歴史を研究している市民サークルがあります。その方たちにガイドをしてもらって、市内に複数ある遺跡を一緒にたずねるっていうのはどうでしょうか。"}, {"k": "spk", "s": "男1", "t": "それもいいね"}, {"k": "spk", "s": "女", "t": "でも、それでは、ガイドをする人によって内容がばらばらになりそうですし、それに、遣跡を巡るとなると長時間歩きますから、子どもには"}, {"k": "spk", "s": "男2", "t": "内容については職員が取りまとめて調整可能だとは思うんですが...では、市民サークルに呼びかけて、何か歴史が学べるような展示会を催したらどうでしょう。市民サークルにとっても、日頃の成果がアピールできて、良い場になると思います。"}, {"k": "spk", "s": "女", "t": "展示会だと歴史好きの子は来てくれるかもしれませんが、そうじゃない子は...やつばり歴史になじみがなくても気軽に参加できるような企画がいいと思います"}, {"k": "spk", "s": "男1", "t": "うーん、小中学生にはゲーム感覚で参加できるものがいいだろうな。で、それを市民サークルに手伝ってもらうことにしよう。こちらでは思いつかないようなアイディアを出してくれたりして、面白いかもしれないし。よし、じゃあ、その方向で考えてみよう。己念イベントとして、どんな企画をすすめることになりましたか。"}, {"k": "ch", "t": "1.古代風のアクセサリーを作る企画"}, {"k": "ch", "t": "2.クイズを解きながら中山城を探検する企画"}, {"k": "ch", "t": "3.市内の遺跡巡りをする企画"}, {"k": "ch", "t": "4.歴史に関する展示会をする企面"}]}, {"head": "テレビでアナウンサーが町長選挙について話しています。", "lines": [{"k": "text", "t": "今月末に行われる円山町の町長選挙には4人が立候補しています。現職の町長である中村氏は、過疎が進む町の活性化にはスキー場の建設が欠かせないと主張しています。その中村氏の対抗馬とされているのは鈴木氏で、自然破壊につがなるとして、スキー場の建設に異議を唱えています。そして今回35歳という異例の若さで立候補した山本氏は、スキー場の建設を支持しっつ、さらにスキー場の建設だけでなく、年間を通して観光客の誘致が見通せるようにすべきだとしています。本田氏は市町村合併による財政支出の削減を進めるべきだと訴え、スキー場建設は税金の無駄遣いだとしています"}, {"k": "spk", "s": "男", "t": "今の町長ってもう10年以上やってるよな。思い切って新しい人にしてもいいんじゃない~"}, {"k": "spk", "s": "女", "t": "そうかな。もうスキー場の用地買収は一部始まってるし、いまさら白紙に撤回したら、これまでの費用とかも無駄になっちゃうでしょう。"}, {"k": "spk", "s": "男", "t": "それはそうだけど、建設しても流行らなかったら、それこそもったいないよ。"}, {"k": "spk", "s": "女", "t": "でも、やりかけちゃったんだし。自然破壊っていうのもわかるけど、それより、過疎化を食い止めてほしいな。私はこれまでの実績を評価したい。"}, {"k": "spk", "s": "男", "t": "ふーん、僕はスキーシーズン以外も、町が賑わうようになればいいとは思うけど。でもそうなる保障、ないでしよ。だから膨大なコストをかけるリストは避けるべきだと思う。"}, {"k": "spk", "s": "女", "t": "そっか。"}, {"k": "spk", "s": "男", "t": "僕は自治体がまとまることによって無駄を省いてほしいな。"}, {"k": "q", "t": "質問1女の人はどの候補者がいいと言っていますか。解答1"}, {"k": "q", "t": "質問2男の人はどの候補者がいいと言っていますか。解答4"}]}], "2016-07": [{"head": "大学で男の学生と女の学生が話しています。", "lines": [{"k": "spk", "s": "男", "t": "先輩、今学期の選択科目、なに取ろうか考えてるんですけど、後一つ決められなくて、今ちよっといいですか?"}, {"k": "spk", "s": "女", "t": "うん。はやし君、専攻は世界史だったよね。"}, {"k": "spk", "s": "男", "t": "はい。ても済か營の視から、今の世界を見られるような授業をとりたいなあと思ってるんです。なるべく人数が少ないクラスがいいんですが.これ、選択できる科目の一覧なんですけど、いくつか候補に丸をつけてあります。"}, {"k": "spk", "s": "女", "t": "見せて。ああ、この済入門って授業ね、去年受けたけど、小人数だったし、そのときニュースになってた世界経済のトピックを取り上げてくれて、面白かった。それから、経済学概論は時代経済を理解するための基礎がしつかり学べるクラスだよ。質問がびしばし飛んできて、緊張するけど、ためになってよかったな。大教室でやる授業なんだけどね。"}, {"k": "spk", "s": "男", "t": "そうですか?"}, {"k": "spk", "s": "女", "t": "あと、経營学ね、普通経営學っていうと、実践的な内容を扱う授業が多いんだけど、この先生は、理論がすきなんだよね。話が上手で、全然退屈しないって評判いいし、去年は学生の数も少なかったよ。それから、西洋経済史、これは毎年人気があって、小人数ってわけじゃないと思うけど、近世ョーロッパの経済のことがわかって、はやし君の専門にも近そうだし、いいんじゃない?"}, {"k": "spk", "s": "男", "t": "そうですね。専門に近いのはカですけど、人数はやつばり少ないほうがいいし、理論が中心の授業より、生の題材から経済を学べるのがいいですね。これにします。ありがとうごさいました男の学生はどの授業を受けますか?"}, {"k": "ch", "t": "1.経済入門"}, {"k": "ch", "t": "2.経済学概論"}, {"k": "ch", "t": "3.経営学"}, {"k": "ch", "t": "4.西洋経済史"}]}, {"head": "スーパーで店長と店員ニ人が話しています。", "lines": [{"k": "spk", "s": "店長", "t": "一人も気づいていると思うけど、近所に競谷店ができてから、うちの店の業績がいまいちなんだよね。"}, {"k": "spk", "s": "店員1", "t": "あちらでは家族向けのイベントに力を入れてますね。うちも対読して、何か家族で楽しめるイベントを企画しましょうよ。"}, {"k": "spk", "s": "店員2", "t": "うーん・・うちは単身者をターゲットにした店だし、会社帰りに立ち寄る人もおおいので、営業時間を延長するというのはどうですか?遅くまで開いていると、ありがたいという人は多いと思います"}, {"k": "spk", "s": "店長", "t": "なるほどね。"}, {"k": "spk", "s": "店員1", "t": "じゃあ、一人暮らしの年齢者向けに、たとえば、配達サービスをしたり、何か高者が集まれるようなイベントを企画したりするのはどうでしょう"}, {"k": "spk", "s": "店長", "t": "は一あ。高齢者か"}, {"k": "spk", "s": "定員2", "t": "あっちは容量の多い商品を充実させて、家族向けを売りにしているようですから、こっちはこれまでどおり単身者をターゲットにして、少量の惣の品揃えを充実させるのはどうですか?野菜や肉の少量パックなんかも増やして。"}, {"k": "spk", "s": "店長", "t": "なるほど。それは高齢者にもニーズがありそうだね。営業時間を延長してもコストに見合う売り上げが確保できるとは限らないし、余所に追提しても勝てないような気がすついりるし、共存するには棲み分けというのは大切かな。将来的には配達サービスなんかも考えないといけないかもねスーバーではこれからどうすることにしましたか?"}, {"k": "ch", "t": "1.家族向けのイベントを企画する"}, {"k": "ch", "t": "2.営業時間を延ばす"}, {"k": "ch", "t": "3.配達サービスをする"}, {"k": "ch", "t": "4.量の少ない商品を増やす"}]}, {"head": "テレビで動物をテーマにした本を紹介しています。", "lines": [{"k": "text", "t": "今日は動物をテーマにした本の中から、お勧めの本を4冊ご紹介します。まず一冊目は「みんなの好きな動物」子供たちに人気の高い動物の表情を写真に収めた本ですアップで見る動物の目や鼻は大迫力で、毛の生え方まで見ることができます。2冊目はいろんな動物、仕掛けのある絵本て、ページをめくると、動物の絵が動き出します。馬がかけたり、サルが木を攀じ登ったり、本当に不思議です。子供も大人も楽しめる一冊です。3冊目は自然の物語、大自然に生きる野生動物の写真集です。写真家が半生をかけ、地球を飛び回って撮った写真、約500枚が掲載されています。そして最後の4冊目は、「熊と私」。森に住む嶽医と傷ついて保護された4うい野生の熊との触れ各いを描いた感動の物語です。美しい文書で綴られ、作者自身による挿絵が添えられています"}, {"k": "spk", "s": "男", "t": "そういえば、甥っ子のたかし君もうすぐ誕生日だよねプレゼントに動物の本なんてどうたろう。顔の細かいところまで見られるなんか、喜ぶんじゃない~"}, {"k": "spk", "s": "女", "t": "そうね。でもたかし君ぐらいの年齢だと、動くもののほうがすきかも。"}, {"k": "spk", "s": "男", "t": "おお、確かに。絵が飛び出す本とか、触って遊べる本がいいかもなあ。じゃ、買ってくるよ。"}, {"k": "spk", "s": "女", "t": "ねえ、私もほしくなっちゃった。世界中の野生動物が見られるっていう、さっきの本、すこくない~一緒に買ってきて"}, {"k": "spk", "s": "男", "t": "うん。でも、動物のお医者さんの話のほうが、君の好みじゃない~"}, {"k": "spk", "s": "女", "t": "うん、今はゆっくり読んでる余裕ないから。"}, {"k": "spk", "s": "男", "t": "そっか。わかった"}, {"k": "q", "t": "質問1ニ人はたかし君にどの本を選びましたか? 2"}, {"k": "q", "t": "質問2男の人は女の人にどの本を買ってくることになりましたか? 3"}]}], "2016-12": [{"head": "会社で男の人と女の人が話しています。", "lines": [{"k": "spk", "s": "男", "t": "中山さん、この前マッサージの店の話してたよね。パソコンの使いすぎなのか、肩の痛みに悩まされていて、会社から近いところ知らない?定時の6時に会社を出れば間に合うところがいいんだけど、それで行った人の感想が分かってると、安心できていいなあ。あと、できれば、料金はあまり高くないほうが。"}, {"k": "spk", "s": "女", "t": "そうですか。会社から10分のところにスッキリという店があります。以前通ってましたが、料金も手ごろですし、元スポーットレーナーが理論に基づいてやってます。腕も確かですただ店は6時半までなんで、早退したほうが無難かもしれません。"}, {"k": "spk", "s": "男", "t": "中山さんが行ってたとこなら、安心だな"}, {"k": "spk", "s": "女", "t": "それから、私の友人が通っていたさわやか堂という店も昔からある店で、いいみたいです。凝りをほぐしてもらうとき、ちょっと痛いらしいんですが、肩こりが治ったそうですよ。こは九時半までで、会社からは5分です。相場より若干高いそうですけど。:男:、え~"}, {"k": "spk", "s": "女", "t": "そういえば、会社から数分のところに山川クリニックって病院ありますよね。行ったことはないんで、よく分かりませんが、病院は健康保険が適用されるかもしれないから、治費は安く済むんじゃないですか。私が鳬て帰るときは、まだやってますよ。"}, {"k": "spk", "s": "男", "t": "そうか。"}, {"k": "spk", "s": "女", "t": "あと、会社から20分かかりますが、太陽という店があります。リラックスできると、ネットで評判がいいんです。良心的な値段ということもあって、人気みたいですよ。時間は八時までです。"}, {"k": "spk", "s": "男", "t": "やつばり行った人の感想が分かってるほうがいいなあ。会社から近くて、定時で帰れば確実に間に合うってことを先するか。料金のことはこの際置いといて。ありがとう。今日行ってみるよ男の人はどこに行くことにしましたか。"}, {"k": "ch", "t": "1.スッキリ"}, {"k": "ch", "t": "2.さわやか堂"}, {"k": "ch", "t": "3.山川クリニック"}, {"k": "ch", "t": "4.太陽"}]}, {"head": "食品の会社で上司と社員ニ人が話しています。", "lines": [{"k": "spk", "s": "男", "t": "三年前に発売した肉の缶吉り上げが薇這いだから、何とかしたいんだ何かいい案はないかな"}, {"k": "spk", "s": "女", "t": "そうですね。発売直後はテレビコマーシャルのおかげで一気に人気が出ましたよね。またやってみるっていうのはどうでしょう。人気の俳やタレントを用して"}, {"k": "spk", "s": "男", "t": "そうだな。みんなに知ってもらえるし、効果は絶大だろうな"}, {"k": "spk", "s": "男2", "t": "ただ、うちぐらいの規模じゃ、新製品でもないのに、大々的な広告は高くついて、難しいんじゃないですか。有名人に出てもらうなら、なおさら.."}, {"k": "spk", "s": "男", "t": "そうなんだよな"}, {"k": "spk", "s": "女", "t": "じゃあ、コンテストを開催するのはどうですか。うちの鶏肉の缶詰をを使った料理のレシピを一般の方から公募して、結果をホームページとかに載せるんです。すでに味付けしてある商品ですが、いろんな料理にもアレンジできることはアピールできますし。テレビコマーシャルに比べたら、経費もぐっと抑えられると思います。"}, {"k": "spk", "s": "男", "t": "なるほどね。"}, {"k": "spk", "s": "男2", "t": "それより、僕はこの際商品自体を改善するべきだと思います。味付け、発売当初からそのままですよね。健康趣向のお客様も年々増えてますし、塩分量や調味料の配合を見直してみるとかどうですか。"}, {"k": "spk", "s": "女", "t": "今の味付けになれているお客様も多いと思いますけど。"}, {"k": "spk", "s": "男", "t": "そうだよな"}, {"k": "spk", "s": "男2", "t": "じゃあ、味のバリエーションを増やすのはどうですか。今は一種類のみですし、やってみる価値はあると思いますけど。"}, {"k": "spk", "s": "男", "t": "マンネリ化を防ぐためにはいいけど、それも費用が嵩みそうだしな。やつばりコストを抑えて、料理の幅の広さを知ってもらえる方法がよさそうだな。それで進めよう。売り上げを伸ばすために何をすることにしましたか?"}, {"k": "ch", "t": "1.テレビでコマーシャルを放送する"}, {"k": "ch", "t": "2.レシピのコンテストを行う"}, {"k": "ch", "t": "3.今ある商品の味を改善する"}, {"k": "ch", "t": "4.味の種類を増やす"}]}, {"head": "ラジオでアナウンサーが美術展について話しています。", "lines": [{"k": "spk", "s": "女1", "t": "今日は四つの美術館で現在開催されているお勧めの燹術展をご紹介します。富田美術館では17世紀から19世紀にかけて描かれたヨーロッパの風景画展が行われています。ほとんどの作品は日本初公開の貴重なものです。19世紀に最盛期を迎えるまでの風景画の変を見ることができます。アーク美術館は再生アート展です。空き缶や使用みのペットボトルなと廃彙された素材を使った作品が見るものに訴えかけてきます。秋山美術館は森山たかし回顧展です。生誕100年を記念し、開催されます。生涯を通して、人を描くことにこだわり続けたその足跡をたどることができます。最後はポニー美術館の体感アート展です。展示された作品を目で見るだけでなく、聞く、触れる、嗅ぐといった体験を通して楽しむことができます。"}, {"k": "spk", "s": "女2", "t": "加藤君、次の週末一緒にどれか見に行かない。"}, {"k": "spk", "s": "男", "t": "うん、いいれ一人の画家の描く絵がどんなふうに変化していくのかって、面白そうじゃない。"}, {"k": "spk", "s": "女2", "t": "私はそれよりも、ヨーロッパの風景画の変に興味あるな。日本に来るのは初めてってものも多いみたいだし、めったに見られないだろうから、この機会に見ておきたいなあ。"}, {"k": "spk", "s": "男", "t": "うんん、確かに見るチャンスなかなかないと思うんだけど、ぼく、景色だけっていうのは、どうもね。"}, {"k": "spk", "s": "女2", "t": "そっか。じゃあ、それは私会社の帰りにでも一人で行くことにするね。それ以外だったら、捨てられたものがどんなふうになるかっていうのも興味あるんだけど。"}, {"k": "spk", "s": "男", "t": "それ、僕もメッセージ性があって面白そうって思ったじゃあ、そこにする~あっ、それか、いろいろな感覚を使うってのもあるね"}, {"k": "spk", "s": "女2", "t": "それも実際に触ったりできて楽しそうなんだけど、すごく人気だって聞いたよ。週末だと、きっと込んでるから、それは別の機会にしない~"}, {"k": "spk", "s": "男", "t": "そうだね。じゃ、決まり、週末、楽しみだね。"}, {"k": "q", "t": "質問1女の人は一人でどの美術館に行きますか。1"}, {"k": "q", "t": "質問2ニ人は次の週末どの美術館に一緒に行きますか。2"}]}], "2017-07": [{"head": "市民センターの事務所で、男の人と女の人が話しています。", "lines": [{"k": "spk", "s": "男", "t": "すみません。来月の15日に、ボランティアグループの研修会で使用する部屋を借りたいんですが"}, {"k": "spk", "s": "女", "t": "はい、何人ぐらいで使えますか"}, {"k": "spk", "s": "男", "t": "30人くらいの予定です。講師に講義をしてもらってから、グループ活動をする予定なので、黒板があって、机が動かせて、参加者が動き回れるようなスペースがほしいんです。"}, {"k": "spk", "s": "女", "t": "30人でしたら、定員30名の第一会議室があいてますよ。机の移動も自由にできます。それから、定員40名の第二会議室は、机は固定されてますが、椅子は自由に動かせます。どちらも黒板は常備してあります。"}, {"k": "spk", "s": "男", "t": "ああ、机も動かせたらいいけど、仕方ないかなあ。定員30人の部屋だと、ぎゅうぎゅうだろうから。"}, {"k": "spk", "s": "女", "t": "あとは、第一会議室の二倍ぐらいの広さの多目的室というのがあります。体操やレクリエーションに使うことが多いんですが、その名のとおり、なんに使ってもいいスペースですから、そこに机といすと黒板を入れることもできます。ただ、準備の作業はお任せすることになりますが"}, {"k": "spk", "s": "男", "t": "なるほど"}, {"k": "spk", "s": "女", "t": "ほかに広いところといえば、200人規模の会議もできる大会議室っていうのもありますよ。机と椅子は固定されてますが、広いですよ。こも黒板は使う場合は、運び込むことになってます"}, {"k": "spk", "s": "男", "t": "そうですか。ううん、やつばり、机が動かせて、部屋もある程度広いほうが、グループ活動がしやすいですね。必要なものは少し早く来て、みんなで運び込むことにします。"}, {"k": "spk", "s": "女", "t": "では、こちらの申込用紙にご記入ください。男の人はどの部屋を借りることにしましたか。1第一会議室2第二会議室3多目的室4大会議室"}]}, {"head": "レストランの店長と店員ニ人が話しています。", "lines": [{"k": "spk", "s": "男1", "t": "近くにオフィスビルが建ってから、ランチタイムの利用客が増えたのはありがたいんだけど、うち店が狭いからすぐ満席になっちゃって。お客さんをお待たせしたり、お断りすることが多くなったよね。何かいい案ないかなあ"}, {"k": "spk", "s": "女", "t": "お店の前に少しスペースがあるので、天気のいい日だけでも、そこにテープルを出して、テラス席を設けるのはどうですか。"}, {"k": "spk", "s": "男2", "t": "でも、その分こちらの負担も大きくなりますよね。席が増えたら、今のスタッフだけで、注文をさばききれるでしょうか。"}, {"k": "spk", "s": "男1", "t": "今の人数では厳しいね。"}, {"k": "spk", "s": "女", "t": "じゃあ、お弁当の販売も始めるのはどうですか。日替わりで、一日一種類だけ、30食程度準備しておくんです。それだと、販売するだけですよ。"}, {"k": "spk", "s": "男2", "t": "ランチタイムはそうかもしれないけど、ランチ前の準備の時間帯は、お弁当の分すごく忙しくなるってことでしょう。ランチの営業時間を延長できませんか。今より、前後一時間程度。そうすれば、お客様の来店時間が少し分散されるんじゃないかと思うんですが"}, {"k": "spk", "s": "男1", "t": "会社のお昼休みの時間ってどこもだいたい同じだからね。そううまく分散されるかな。"}, {"k": "spk", "s": "男2", "t": "じゃあ、ランチタイムに入る従業員を増やすことはできませんか。調理や後片付けの時間を短縮するために。"}, {"k": "spk", "s": "男1", "t": "そうだなあ。ただでさえ狭いキッチンにこれ以上入ると、作業しにくくなるなあ。準備はちょっと大変になるかもしれないけど、作っとくっていうのは、悪くないと思うなあ。うん、それでやってみよう。問題を解決するために、何をすることにしましたか。1テラス席を設ける2弁当を販売する3ランチの営業時間を延ばす4従業員を増やす"}]}, {"head": "食品会社の新人研修で講師が話しています。", "lines": [{"k": "spk", "s": "男1", "t": "ええ、今日までの研修て、商品の開発から販売までの流れについて一通りお話しました明日は四つのグループに分かれて各業務の模擬体験をしてもらいます。今から各グループの説明をします。まず、青グループは市場調査をします。夏向けの商品の開発に向けて消費者のニーズを把握する調査を計画します。赤グループは商品企画。実際の顧客調査の結果をもとに、新商品の構想をねって、提案してください。それから、黄色グループ。このグループには今開発中の商品の商品名やパッケージデサインの案を考えてもらいます。緑グループは営業。新商品を店頭に置いてもらうため、販売店との交渉の作戦を考えます。この後、希望するグループを書いて出してもらいます。"}, {"k": "spk", "s": "女", "t": "どれにしますか。山田さんは大学でマーケティングを専攻してたんですよね。やつばりそのグループですか。"}, {"k": "spk", "s": "男2", "t": "ううん、市場調査の結果を分析して、それをどう開発に生かすかっていうほうに興味があるんで、そっちですね。自分が手がけた商品を世に出してみたいですし。"}, {"k": "spk", "s": "女", "t": "なるほど。私はいい商品を多くの人に手にとってもらえるようにどんな工夫ができるかを考えてみたいんです。"}, {"k": "spk", "s": "男2", "t": "お店に商品を置いてもらえるかどうかって営業のカですからね"}, {"k": "spk", "s": "女", "t": "そうなんですけど。私がやりたいのは、商品をより魅力的に消費者に見せるっていうほうです"}, {"k": "spk", "s": "男2", "t": "ああ。"}, {"k": "q", "t": "質問1男の人はどのグループを希望しますか。(正解:2)"}, {"k": "q", "t": "質問2女の人はどのグループを希望しますか。(正解:3)"}]}], "2017-12": [{"head": "大学の学生課で、男の学生と職員が話しています。", "lines": [{"k": "spk", "s": "男", "t": "すみません、夏休みに短期のアルバイトをしたいと思ってるんですか"}, {"k": "spk", "s": "女", "t": "はい。どんなところが希望ですか。"}, {"k": "spk", "s": "男", "t": "僕、留学経験があって英語が得意なので、その力が生かせるところがいいです。卒業したら海外で事業を展開している会社に就職したいと思っているので、そういう会社ならなおさらいいですが。あ、それから、8月前半の二週間は都合が悪いので、それ以外でできるところを探しています。"}, {"k": "spk", "s": "女", "t": "ちょっと調べてみますね。次の四つはどうですか。まず、海外でも広く事業を展開している山下商社、期間は8月後半の二週間ですし、ちょうどいいですね。あ、業務内容は事務補助で、外国語は不要となっていますが"}, {"k": "spk", "s": "男", "t": "そうですか。"}, {"k": "spk", "s": "女", "t": "次は桜デパート。海外には進出していませんが、最近外国人のお客さんが急増しているようで、店内で英語の通訳を行う仕事です。期間は、7月1日から9月末までのどこかで三週間。開始日は応相談と書いてありますね。それから、国際文化センターこは、主に日本文化を世界に向けて発信したり、交換留学プログラムを運営したりしている組織です。"}, {"k": "spk", "s": "女", "t": "期間は、七月中旬から下旬の二週間。仕事の内容は、ホームステープログラムに関する事務作業とあります。あ、外国語ができなくても可能な業務と書かれてますね。最後は黒田工業、こは一昨年海外に進出したばかりで、事業を拡充するための調査結果を英語で入力する仕事です。えーっと、7月中旬から8月上旬の三週間続けて勤務できる人だそうです。"}, {"k": "spk", "s": "男", "t": "うん、どこもよさそうですね。留学生の支援は自分の留学経験が生かせていいと思うけど、やつばり語学力が発揮できるところがいいです。日程が合わないところはどうしようもないし、海外に進出してるかどうかっていうのはそこまでこだわってるわけじゃないので、ここに申し込みます。ありがとうございました男の学生は、どのアルバイトに申し込みますか。"}, {"k": "ch", "t": "1.山下商社"}, {"k": "ch", "t": "2.さくらデパート"}, {"k": "ch", "t": "3.国際文化センター"}, {"k": "ch", "t": "4.黒田工業"}]}, {"head": "スーパーで魚売り場の責任者と社員ニ人が話しています。", "lines": [{"k": "spk", "s": "男1", "t": "このところ鮮魚の売れ行きがイマイチだね。何か手を打たない限り状況変わらないと思うんだけど。いい案ないかな"}, {"k": "spk", "s": "男2", "t": "うーん、そう言えば家で魚の内臓とか骨を処理して、切り身にするのが面倒だっていう人、多いんですよね。希望するお客さんには、売り場で魚を切り身にするサービスを始めてはどうでしょうか。魚を捌く専属のスタッフと場所は必要になりますが"}, {"k": "spk", "s": "男1", "t": "うん。"}, {"k": "spk", "s": "男2", "t": "または、魚料理はいつも同じような献立になってしまって飽きちゃうという話もよく聞くので、ショーケースの横に、その日売ってる魚に合ったちょっと珍しいレシピを作って用意しておくのもいいと思います"}, {"k": "spk", "s": "女", "t": "あのう、今は共働きの家庭も増えていて、料理にあまり時間をかけられないっていう人も少なくないですよね。ですから、予め魚の骨をとって、調味料につけておいて、あとは焼くだけのような半加工食品を増やすのがいいと思うんですが"}, {"k": "spk", "s": "男1", "t": "半加工食品か"}, {"k": "spk", "s": "女", "t": "それか、いっそのこと、魚を使ったお惣菜の種類を増やすのはどうですか。そのまま食卓に出せますし。鮮魚ではありませんが、魚の売り上げにつながると思います。"}, {"k": "spk", "s": "男1", "t": "そうだね。うーん、いろんなアイデアありがとう。どの案もいいんだけど、専属のスタッフやスペースを確保しなきゃならないのは、負担が大きいし、それに、うちは厳選した新鮮な魚を仕入れてるのが売りだから、味をつけておいたりするのはちょっとね。"}, {"k": "spk", "s": "男2", "t": "じゃあ、決まりですね。"}, {"k": "spk", "s": "男1", "t": "うん、さっそく準備を進めよう。問題を解決するために、どうすることにしましたか。"}, {"k": "ch", "t": "1.売り場で魚を切り身にするサービスをする。"}, {"k": "text", "t": "売り場にレシピを置いておく。"}, {"k": "ch", "t": "3.魚の骨をとって、味付けをしてから売る。"}, {"k": "ch", "t": "4.魚を使った惣菜の種類を増やす。"}]}, {"head": "ショッビングセンターで、店員がアナウンスをしています。", "lines": [{"k": "spk", "s": "男", "t": "ええ、当店ではただ今大抽選会を開催しております。お買い物千円ごとに一枚、応募カードを差し上げますので、次の四つの景品からお好きなものを一つ選んでカードにご記入の上、応募箱に入れてください。一番は海の幸グルメセット、とれたての魚介を漁港から直送します。2番は、有名洋菓子店黒崎の焼き菓子の詰め合わせ、人気でなかなか手に入らないお品です。3番は、オペラ公演のご招待券。お好きな公演を選んで特別席でご観賞いただけます。4番は、大型望遠鏡。これを機に天体観測はいかがでしょうか。1番は30名様、2番は25名様、3番は3名様、4番は1名様にあたります。詳しくは応募カードをご覧ください。"}, {"k": "spk", "s": "男", "t": "僕たち、さっきの食事で応募カード3枚もらったよ。ほら、これ。まずはそれぞれ好きなのを一つ選ばない~斉藤さんは演劇好きだし、やつばりチケッ"}, {"k": "spk", "s": "女", "t": "うん、特別席なんて座ったことないし、それも捨てがたいんだけど、わたし、甘いものに目がなくて。入手困難だって聞くとますますほしくなっちゃうなあ。うーん、困ったなあ、どっちにしよう。野村君は~"}, {"k": "spk", "s": "男", "t": "僕は、最初星の観察をしてみたいなあって思ったけど、一人にしか当たらないなんて確率低いよね"}, {"k": "spk", "s": "女", "t": "じゃあ、当選人数が一番多いのにしたら~"}, {"k": "spk", "s": "男", "t": "うん、でも魚はそんなに好きじゃないから。その次に多いのにする。斉藤さんはどっちか決められないなら、2枚使って迷ってるのを一つに応募すればいいよ。"}, {"k": "spk", "s": "女", "t": "え、いいの~ありがとう、じゃそうする。"}, {"k": "q", "t": "質問1男の人は、何番の景品に応募しますか。(正解:2)"}, {"k": "q", "t": "質問2女の人は、何番の景品に応募しますか。(正解:3)"}]}], "2018-07": [{"head": "社会で女の人と男の人が話しています。", "lines": [{"k": "spk", "s": "女", "t": "今度のセミナーの会場、200名収容可能な会場見つかった?"}, {"k": "spk", "s": "男", "t": "あっ、課長、はい、候補を四つに絞ってリストにしました。駅から徒歩圏内で駐車場があるところ、あと手荷物を預かってくれるサービスもあるといいということでしたよね。"}, {"k": "spk", "s": "女", "t": "そうね。"}, {"k": "spk", "s": "男", "t": "ーっは去年出来たばかりの木村会館です。駅から徒歩5分とアクセスもよく駐車場もあります。建物も綺麗でセミナーには最適ですが、荷物は預かってくれないそうです。それから山田ホテルも駅から徒歩5分ほどにあります。こちらはフロントで荷物を預かってくれます。広めの駐車場もあるんですが、建物が若干古いですね。"}, {"k": "spk", "s": "女", "t": "そう。"}, {"k": "spk", "s": "男", "t": "次は井上セミナーハウス、駅から徒歩15分ですが、徒歩圏内だと思います。バスの本数も多いですし、駐車場も広くて、車で来る参加者が多い場合にも安心かと思います。荷物預かりサービスはありませんが、建物の中にコインロッカーがあります。"}, {"k": "spk", "s": "女", "t": "駐車場が広いのはいいわね。ただ、15分ねえ、今回は遠方からの参加者も多そうだし、泊まりで来られる方は荷物が多いし、やつばり徒歩10分圏内で、ある程度車が置ける所がいいわね"}, {"k": "spk", "s": "男", "t": "駅からの近さという点では高山ホールですれ駅の真上にあって、アクセスは非常にいいです。"}, {"k": "spk", "s": "女", "t": "真上れ、いわね。"}, {"k": "spk", "s": "男", "t": "はい、荷物も預かってくれるんですが、駅なので駐車場の確保は難しいですね。"}, {"k": "spk", "s": "女", "t": "そう~駅の上は魅力的だけど、やつばり駐車場があったほうがいいわね。で、荷物も会場に預けられて、近いところって言うと、ここかなあ。予約を入れてくれる~女の人はどの会場を予約するよう頼みましたか。"}, {"k": "ch", "t": "1.木村会館"}, {"k": "ch", "t": "2.山田ホテル"}, {"k": "ch", "t": "3.井上セミナーノ、ウス"}, {"k": "ch", "t": "4.高山ホール"}]}, {"head": "美術館の職員三人が話しています。", "lines": [{"k": "spk", "s": "男1", "t": "最近子供の来場者が減ってるよね。小学校低学年ぐらいの子供にも絵に興味を持ってもらえるようにしたいと思うんだけど、何かいい方法ないかな"}, {"k": "spk", "s": "女", "t": "そうですね。子供向けに作品の説明をパンフレットにして配ったらどうでしょうか。作品の脇にある解説は子供には難しいので"}, {"k": "spk", "s": "男1", "t": "うん、そうだね"}, {"k": "spk", "s": "女", "t": "あと、好きな絵を真似て書けるように、画用紙と色鉛筆を貸し出すのもいいかもしれません。もともと絵を描くのが好きな子向けの方法かもしれませんが"}, {"k": "spk", "s": "男1", "t": "うん"}, {"k": "spk", "s": "男2", "t": "あのう、子供向けなら遊び感覚のあるものが喜ばれるんしゃないでしょうか。絵をさあっと見るんじゃなく、一枚一枚じっくり見るきっかけになるように。例えば、クイズを出すとか"}, {"k": "spk", "s": "男1", "t": "なるほど"}, {"k": "spk", "s": "男2", "t": "あと他の方法としては、入り口で絵の一部分のコヒーを数枚渡しておいて、それぞれどの作品かを探すのもパズルみたいで楽しみながら鑑賞できると思います。作るのちょっと手間かかりますが"}, {"k": "spk", "s": "男1", "t": "子供はそういうの好きそうだね。うん、どの案もいいけど、特に、絵が好きってわけじゃない子の興味も惹けるのがいいね。絵の説明は簡単にしたとしても、小学校1、2年の子に読んでもらうように作るのは難しいから、そうすると、あとのふたっかな。"}, {"k": "spk", "s": "女", "t": "そうですね。個人的にはいくらコピーと言っても絵を切るのは抵抗がありますが"}, {"k": "spk", "s": "男1", "t": "それもそうだね。じゃ、簡単に準備できるほうから始めようか。この美術館では、子供向けにどんな工夫をすることにしましたか。"}, {"k": "ch", "t": "1.子供向けのパンフレットを配る"}, {"k": "ch", "t": "2.画用紙と色鉛筆を貸し出す"}, {"k": "ch", "t": "3.絵に関するクイズを用意する"}, {"k": "ch", "t": "4.絵の一部から作品を探すゲームを用意する"}]}, {"head": "ラジオを聞いて夫婦が話しています。", "lines": [{"k": "spk", "s": "女1", "t": "今日は紅葉が美しい山を四つご紹介します。まず、ご家族でハイキングを楽しむのにもってこいなのが赤山です。麓のハイキングコースはなだらかで、一時間ほどで紅葉狩りが満喫できます。次の青山は麓からロープウェーを利用すると10分ほどで山頂に着きます。歩いても片道約一時間ですので、片道だけ歩いて、色付く紅葉を楽しむのもお勧めです。それから、緑山はロープウェーがなく、麓から山頂まで片道約三時間かかりますが、木の種類が多く、紅葉の美しさは全国的に知られています。最後は白山です。こちらは全行程歩くと二日かかる本格的な登山コースですが、山頂から見渡す紅葉は一生に一度は見る価値があると言われる絶景スポットです。"}, {"k": "spk", "s": "男", "t": "へえ、一生に一度は見る価値があるってどんな景色なんだろう。見てみたいなあ。ちょっと遠いけど、今週末は三日間の連休だし、行ってみようか。"}, {"k": "spk", "s": "女2", "t": "あれ、言ってなかった~今度の三連休は仕事休めないの、ごめん。来週末に日帰りで行ける山に行くのはどう~"}, {"k": "spk", "s": "男", "t": "うん、いいよ。ハイキングだと少し物足りないかな。行きは一時間歩いて、もし疲れたら帰りはロープウェーも使えるところにする~"}, {"k": "spk", "s": "女2", "t": "どうせなら、紅葉が有名なほうがいいなあ。私長く歩くの平気だよ。"}, {"k": "spk", "s": "男", "t": "じゃ、来週末そこへ行こう"}, {"k": "spk", "s": "女2", "t": "うん、で、何山だったつけ~一生に一度はってところ、せつかくの三連休だし、友達を誘って行ってみたら~"}, {"k": "spk", "s": "男", "t": "そうだね。一人で家にいるのは退屈だし、そうするよ。"}, {"k": "q", "t": "質問1ニ人は来週の週末どの山へ行きますか。(正解:3)"}, {"k": "q", "t": "質問2男の人は今週の三連休にどの山へ行きますか。(正解:4)"}]}], "2018-12": [{"head": "パソコン売り場で店員と女の人が話しています。", "lines": [{"k": "spk", "s": "男", "t": "お客様、ノートパソコンをお探しですか。"}, {"k": "spk", "s": "女", "t": "はい。長時間使っても目が疲れにくいものがいいんです。小学生の娘用なので、有害なサイトへのアクセスを制限するソフトがインストールされてて、できれば6万円ぐらいまででと考えてるんですが・・"}, {"k": "spk", "s": "男", "t": "目への負担と安全性をご心配されているということですね。こちらのパソコン、マリンはいかがでしょうか。"}, {"k": "spk", "s": "女", "t": "はあ。"}, {"k": "spk", "s": "男", "t": "価格は8万2千円と少しオーバーしますが、悪質なサイトをプロックするソフトも入ってますし、長時間使用しても目が疲れにくい画面が採用されています。"}, {"k": "spk", "s": "女", "t": "結構な値段するもんなんですね。あの、もう少し安いのもありますか。"}, {"k": "spk", "s": "男", "t": "お手頃価格のものですとこちらのパソコン、スターが4万5千円、ベストが6万円とお勧めです。ベストは目の負担を軽減する仕様になっていますが、スターはなっていないですね安全性のソフトはどちらも入っていないですが、ご自身でインストールされるならソフトは別売りで5千円で販売しています"}, {"k": "spk", "s": "女", "t": "そうですか。"}, {"k": "spk", "s": "男", "t": "それと、こちらのダイヤという製品も目への負担が少ないです。通常7万5千円なんですが、今ならキャンペーン中で本体が1万円引き、それに安全性ソフトを5千円でご購入いただくと当店で無料てインストールします。でもマリンと同様、こちらも6万円は超えちゃいますね。"}, {"k": "spk", "s": "女", "t": "うーん、有害サイトへのアクセス防止は譲れないですね。それと目が疲れにくいことも。自分でインストールするのはそういうの得意じゃないのでやめときます。予算内に収めたいのは山々だけど、安い方ならまあ、いいか。これにします。女の人はどのパソコンを買うことにしましたか。"}, {"k": "ch", "t": "1.マリン"}, {"k": "ch", "t": "2.スター"}, {"k": "ch", "t": "3.ベスト"}, {"k": "ch", "t": "4.ダイヤ"}]}, {"head": "内科のクリニックで、院長と受付スタッフ2人が話しています。", "lines": [{"k": "spk", "s": "女1", "t": "近頃、近隣にマンションが建ったせいか、患者さんが増えて診察の待ち時間が長くなったでしょう。少しでも快適に過ごしてもらえるよう、いい考えない?"}, {"k": "spk", "s": "男", "t": "あの、待合室の椅子、4人掛けの長椅子で隣の人との距離が近くて少し窮屈な感じがします。一人掛けに変えられたらと思うんですが・"}, {"k": "spk", "s": "女2", "t": "椅子は床に固定されてるから工事が必要ですよ。それに一人掛けにすると座席の総数か減るんじゃないですか。あの、先日ある病院に行ったら、待合室の壁にプロジェクターて大きく映画流してて、待ち時間があっという間に思えたんです。"}, {"k": "spk", "s": "女1", "t": "それ、テレビじゃだめなの?"}, {"k": "spk", "s": "女2", "t": "大画面だから映画館の気分で集中して時間を忘れられるんです。プロジェクターもプレーヤーもクリニックにあるから大きな出費もないですし、字幕付きで音量絞れば、うるさくはならないかと・男.なるほど。僕も他の病院でいいと思ったのがあります。マッサージチェアが3,4台置いてあって、患者さんが交替で使えるんですけど、気持ちいいってお年寄りもお勤めの方もすごく喜んでました。でも、高額か・"}, {"k": "spk", "s": "女1", "t": "それに場所も取るから。"}, {"k": "spk", "s": "女2", "t": "あの、最近はインターネットで予約できる病院も多いですよね。よやくせいしんさつ男.予約制ても時間が押して待たされることありますけどね。あ、でも、どこまで診察が進んじゅんばんだかネットでわかるようにすればいいのか。順番が近くなったら来ればいいので、待ち時間を有効に使えます。かんじゃ"}, {"k": "spk", "s": "女1", "t": "うちはお年寄りの患者さんが多くて、インターネットが使えない方もいるの。"}, {"k": "spk", "s": "女2", "t": "そうですよね。ぐあいちょうきてきまんせいてきこんぼんてきさく"}, {"k": "spk", "s": "女1", "t": "混み具合が長期的、慢性的になるなら、そういう根本的な策が必要だけど、しばらく様子よさん見てからそれは考えよう。予算の都合もあるし、まずは今あるものを活用できるさっきの案でいこう。クリニックではますどうすることにしましたか。"}, {"k": "ch", "t": "1.待合室の椅子を変える"}, {"k": "ch", "t": "2.待合室にプロジェクターで映画を流す"}, {"k": "ch", "t": "3.待合室にマッサージチェアを置く"}, {"k": "ch", "t": "4.インターネットで予約できるようにする"}, {"k": "text", "t": "えんげき"}]}, {"head": "テレビでアナウンサーが新しいスタイルの演劇について話しています。", "lines": [{"k": "text", "t": "かんきやくさまざまかたちのうどうてきえんげきわだい"}, {"k": "spk", "s": "女", "t": "今、観客が様々な形で能動的に関われるスタイルの演劇が話題になっています「ある1げきだんえんげきてんかいまくあいかんきやく日」という劇団さくらの演劇は前半上演後、後半の話の展開をどうするか幕間に観客がたすうけつアンケートに答えて多数決で決まるというもの。それから劇団ジョイの「ファミリー」ぶたい選ばれた観客が舞台に上がり、ちょっとした役をその場で演じることができます。そんどきようこうえんな度胸はないという方、ミュージカル「大空へ」はどうでしょう。10年にわたり公演さしゆだいかながじまくぶたいうつだれてきましたが、今ではあのお馴染みの主題歌が流れると字幕が舞台に映し出され、客席で観客が同時に声を合わせて歌うんだとか。ミステリーものでは劇団ほたるの「砂のはんにんげきちゅうすいりけいたいでんわかいとう家」。事件の犯人は劇中では明かされず、観客が推理をして携帯電話で回答するんですしんかが、後日、その回答結果と共に真実がメールで配信されます。このような進化したスタイかんきやくそうかくとくルは新たな観客層を獲得することでしょう。げき"}, {"k": "spk", "s": "男", "t": "筋書きが決まってない劇ってライプ感があってわくわくするなあ。げきじよう"}, {"k": "spk", "s": "女2", "t": "いったいどんな風になるんだろうね。私もどれか参加してみたい。そうだなー、劇場みたいなおっきな空間で思い切り声出せるなんてめったにないことだからそれがいい。"}, {"k": "spk", "s": "男", "t": "人前でセリフ言うなんて緊張しないの?すごいね。僕にはとても・"}, {"k": "spk", "s": "女2", "t": "そうじゃなくて、皆で合唱したいの。スカっとするだろうな男.なんだ。僕は自分がストーリーの決定に参加できるなんて思ってもみなかったから、やっばりそれ見に行きたいな"}, {"k": "q", "t": "質問1女の人はどの演劇を見に行きたいと言っていますか。3"}, {"k": "q", "t": "質問2男の人はどの演劇を見に行きたいと言っていますか。1"}]}], "2019-07": [{"head": "電話で翻訳会社の人と男の人が話しています。", "lines": [{"k": "spk", "s": "女", "t": "はい、さくら翻訳サービスでございます"}, {"k": "spk", "s": "男", "t": "あのう、英語で書いた会社案内のチェックをお願いできますか。医機器の会社なんですけど。すこし、急いでるので、一週間ぐらいで仕上げてもらいたいんです。"}, {"k": "spk", "s": "女", "t": "はい。"}, {"k": "spk", "s": "男", "t": "それと、納品後に確認したいことが出てくるかもしれないので、チェックを何回か頼めるとありがたいです"}, {"k": "spk", "s": "女", "t": "承知しました。再チェックの可能性があるということですね。ええ、四つのプランがあるんですが。一番こ利用が多いのは本チ=ックプランです。五日以内に納品て料崟も一番安いです。実際の料崟は原橋の長さによって決まります。再チェックは一回のみ無料でできますが、それ以上になると、追加料金が発生します。"}, {"k": "spk", "s": "男", "t": "ああ。"}, {"k": "spk", "s": "女", "t": "お急ぎなら、スピードプランというのもありますの長さが3000語以内の場合しかお申し込みいただけないんですが、申し込みの翌日に納品可能です。再チェックはこちらも一回のみ無料です"}, {"k": "spk", "s": "男", "t": "3000語か。長さは大丈夫だな。うん、再チェックは一回じゃ終わらないだろうな。あとつのプランはどういうものですか。"}, {"k": "spk", "s": "女", "t": "はい、安心プランというのは追加料金なしで何度でも再チェックができるプランです。その分、料崟が高めですが、再チェックを三回以上するなら、基本チェックプランより、お得ですよ。納品は五日以内です。"}, {"k": "spk", "s": "男", "t": "そうですか。"}, {"k": "spk", "s": "女", "t": "それから、専門チェックプラン、これは内容に合わせて、外部の専門家と連携してチェックをするプランです。納品まで約二週間かかるんですが。再チェックの依頼も何度でもできます。専門家と連携する分、料金がすこし高くなりますが"}, {"k": "spk", "s": "男", "t": "そうですか。専門用語の確誌とかはこっちでもできるから。外部の専門家にまで頼まなくてもいいかな。ええと、納品は翌日じゃなくてもいいんで、追加料金が発生しないっていうさっきのプランでお願いします。"}, {"k": "q", "t": "男の人はどのプランに申し込みますか。"}, {"k": "ch", "t": "1.本チ=ックプラン"}, {"k": "ch", "t": "2.スピードプラン"}, {"k": "ch", "t": "3.安心プラン"}, {"k": "ch", "t": "4.専門チェックプラン"}]}, {"head": "パン屋で店長と店員ニ人が話しています。", "lines": [{"k": "spk", "s": "店長", "t": "最近、車いすに乗ったお客さんが増えたよね。ちょっと買い物しにくそうに見えたんだけど。どうしたらいいかな"}, {"k": "spk", "s": "店員", "t": "近くにできた高暑向けのマンションの方がいらしてるみたいですね。今日も一人いらっしやったんですけど、他のお客様がいたからか、店に入らずに帰られたんです。店員(男):うちの店、それほど広くないですから。車いすだと商品にぶつかりそうになって気を遣われるみたいですね。"}, {"k": "spk", "s": "店長", "t": "うーん。店員(男):店内のレイアウトをすこし変えるのはどうですか。棚のほかに中央の大きなテープルにもパンを並べてますよね。あれを小さくすれば通路を広く取れませんかね。"}, {"k": "spk", "s": "店長", "t": "ああ、そうだね。前に使ってたもう少し小さいのかまだ庫にあるから。店員(女):それより、店の中で買い物しなくてもいいようにしたほうがいいんじゃないですか。"}, {"k": "spk", "s": "店長", "t": "というと~店員(女):外にワゴンを出して、人気のパンを売るとか店員(男):でも、みなさん店の中に入って、いろんなパン見たいんじゃないかと思いますけどあっ、レジのカウンター、車いすの方にとってはすこし高いのでお金を払うとき、不便そうですよね。カウンターの高さを低くするのはどうですか。"}, {"k": "spk", "s": "店長", "t": "うんん、工事が必要になるから、すぐには難しいけどね店員(女):あとは、ホームページから注文できるようにして、商品を配達するのもいいんじゃないですか。"}, {"k": "spk", "s": "店長", "t": "そうだね。配達したり外で売ったりするとなると、スタッフを増やす必要が出てくるよね。すぐにできることっていうと、さっきの案かな。早速やってみよう。この店ではどうすることにしましたか。"}, {"k": "ch", "t": "1.パンを並べるテープルを小さいものに変える"}, {"k": "ch", "t": "2.店の前でパンを冗る"}, {"k": "ch", "t": "3.会計のカウンターを低くする"}, {"k": "ch", "t": "4.インターネットで注文を受ける"}]}, {"head": "会社の研修で講師が話しています。", "lines": [{"k": "spk", "s": "講師", "t": "ええ、商品の開発に当たっては、チームを組んで仕事をすることがよくありますが。成果を出すチームには四つのタイプの人がバランスよく配置されているものです。まず、タイプ1は新しいアイディアを次から次へと出すタイプ。ええ、タイプ2は出されたアイディアを商品の形にしていく実践力のある人。それから、タイプ3はデータ収集や資料筰成など、決められたことを実に正確にやり邃げる人。そして最後のタイプ4はムードメーカー。メンバーの間のコミュニケーションを円滑にして雰囲気をよくする人です。一人の人が複数のタイプを兼ねていてもいいですし、チームが変われば、役割が交替することもありますよ。"}, {"k": "spk", "s": "女", "t": "なるほど、今回の開発チーム、あと一人メンバーを選ばないといけないけど、どんなタイプの人がいいと思う"}, {"k": "spk", "s": "男", "t": "アイディアマンはすでにいるからね。アイディアを具徠な商品にしていける人が必要だよね。"}, {"k": "spk", "s": "女", "t": "うーん、それは今のメンバーでもできるんじゃない。それより、息詰まったときに関係が悪くなったりしないように、みんなの間をつないで士気をあげてくれる人が必要だと思う。"}, {"k": "spk", "s": "男", "t": "それにびったりの人はここにいるじゃない。"}, {"k": "spk", "s": "女", "t": "えっ~私のこと~私は決まったことをコッコツやるタイプだと思ってるんだけど。"}, {"k": "q", "t": "質問1男の人は今回のチームにどのタイプの人が必要だと言っていますか。2"}, {"k": "q", "t": "質問2女の人は今回のチームにどのタイプの人が必要だと言っていますか。4"}]}], "2019-12": [{"head": "男の人と女の人が漁業に関する文献について話しています。", "lines": [{"k": "spk", "s": "男", "t": "僕、来月から北海の漁業組合でシステムエンジニアとして働くんだ。漁業の知識はいらぎよかくりようげんしようないって言うんだけど。日本の漁獲量の減少問題ぐらいは把握しときたくて。加藤さん、大学の時、海の資源を守る活動してたよね。"}, {"k": "spk", "s": "女", "t": "うん。"}, {"k": "spk", "s": "男", "t": "参考になりそうな本があったら、教えてもらえない?漁獲量がいつ頃からどう変わってきたか。統計データで示されてるのがいいんだけど。それと、資源を守るための国内での最近の取り組みも知りたいんた礎知のない僕でも読みやすくて分厚くないのがいいなあ。ぎよぎう"}, {"k": "spk", "s": "女", "t": "ええとね。基礎的なものでいえば、日本の漁っていう本かなあ。漁獲量の減少とかいろんなデータが図表でわかりやすく出てるし、国内の漁業についてコンパクトにまとめられてて読みやすいよ。あっ、北海道なら北海道の漁業って本がおすすめ。北海道の漁業の歴史が詳しく記臻されてて、資源薇や漁薇のをなんかのデータも豊富データが多い分、本の厚みはあるけど、まあ、頑張れば読めると思うよ。"}, {"k": "spk", "s": "男", "t": "ヘーえ、どっちも味深いなあ。"}, {"k": "spk", "s": "女", "t": "両方とも資源を守る活動も載ってたよ。たた、籍箭の出版だから、最近の取り組みじゃないなあ、あっ、そうだ。漁業の未来っていうのもあった。漁獲量減少とそれに対する国内各地でのここ数年の対棗が中記、に扱われてて、データが多くて、報舎書の形で書かれてるんだ。でも、かなりのページ数だから、ちょっと読むのはきついかも"}, {"k": "spk", "s": "男", "t": "いろいろあるんだね。"}, {"k": "spk", "s": "女", "t": "読みやすさで言うなら、新しい漁業。漁獲量変剏のデータはなかったような気がするけど。を源保護に向けた世界各国の新しい漁業の形が紹介されてて、日本も取り上げられてる。情報も新しいよ。いま紹介した本は四つとも中央図書館に置いてあるはず"}, {"k": "spk", "s": "男", "t": "どれもよさそうだけど、自分がいま知りたいことが網羅されてるものから読んでみるよ。やつばり、取り組みは新しいものがいいから、分厚いのをちゃんと読めるか分からないけど、図書館で借りてみる。男も人は図書館でまずどの本を借りることにしましたか。。"}, {"k": "ch", "t": "1.日本の漁業"}, {"k": "ch", "t": "2.北海道の漁業"}, {"k": "ch", "t": "3.漁業の未来"}, {"k": "ch", "t": "4.新しい漁業"}]}, {"head": "家電量販店のカメラ売り場で、店長と店員2人が話しています。", "lines": [{"k": "spk", "s": "店長", "t": "新発売の一眼レフカメラトミーだけど、売り上げが伸び悩んでるんだよ。八万円台で安くはないから、そう一気に売れるものでもないけど、何がいい案ないかな。店員(女):あのう、購入暑にプレゼントしてる黒のカメラケースですが、色やデサインのことなる、おしゃれなのを薮類用意して、その中から選べるようにするとかどうですか。ファッションの一部として、カメラ持ち歩く人も増えてますし。"}, {"k": "spk", "s": "店長", "t": "確かに、いま差し上げてるのはおしやれとは言えないなあ。店員(女):それか購入者に箙簓講蓙を血料で﨎できる血を付けるっていうのもいいんじゃないでしょうか。プロのカメラマンに依頼して講座を開徹するんです。店員(男):商品自体の魅力が伝わらないかぎり、売り上げには繋がらないんじゃん。店員(女):特典がっくって、費者には力的ですよ。トミーならではの機能を存分に使って、講座をやってもらえば、使いこなせるようにもなって、喜ばれると思います。店員(男):決して安い買い物じゃないから、簡単には購入に踏み切れないんだと思います。ですから、商品を貸出して、24時間自由に使ってもらうっていうのはどうでしょう。10台ほど用意して、いい製品だから、良さが分かれば、得して買ってもらえるんじゃないかと。店員(女):でも、壊されたりしたら。"}, {"k": "spk", "s": "店長", "t": "その可能性もあるけど、弁償の契約をつけるっていう手もあるか店員(男)このさい思い切ってと思うんです。それが無理だとしたら、トミーで撮った作品を募って、入口のところで展示会を開くのもいいかと、トミーは初心者ても結構うまく撮れます。宣伝になりますよ。"}, {"k": "spk", "s": "店長", "t": "うん。その企画は贈入暑がある程度増えたらやってみよう。いまはまだそんなに集まらないだろう。うん、いろんな案が出たけと、贈入暑に何をつていうより、性罷の点さを肌てじてもらって、欲しいと思って買ってもらうのはいいと思うから、まずは先の案をやってみよう。カメラの売り上げを伸ばすために、まず、何をすることにしましたか。"}, {"k": "ch", "t": "1.おしやれなカメラケースをプレゼントする"}, {"k": "ch", "t": "2.ただで講座が受けられる特典をつける"}, {"k": "ch", "t": "3.カメラの一日貸出サービスを始める"}, {"k": "ch", "t": "4.写真の展示会を開いて宣篌する"}]}, {"head": "ラジオでアナウンサーが変身ヒーロー番組について話しています。", "lines": [{"k": "text", "t": "アナウンサー:子供たちが好きな変寡ヒーロー番組といえば、いろいろありますが、赤、青、黄色など、若者たちがそれぞれ色別のヒーローに変身して敵を倒す戦隊シリーズは今も続き、人気は表えることがありません。中でも、15年前に大流行した4レンジャーはメンバー4人のキャラクター設定がそれまでとは全く違う個性的なもので、当時、大人気でした。4レンジャー以前の番組では、赤のヒーローといえば、熱的なリーダー。青のヒーローはクールで知的なタイプというのが定番でした。ところが、4レンジャーでは、なんと赤がクールな頭脳派で、少し臆病暑に、そして、青は明るいお調子者と、いずれもヒーローらしからぬキャラクターに。更に、緑は身体能力こそメンバー随一だけれど、わがままで、わが道を行くタイプ。そんな三人をまとめあげ、リードするのが、情にあふれた黄色とそれまでの色のイメージを覆すキャラクターに子供たちは魅了されました。"}, {"k": "spk", "s": "男", "t": "4レンジャー、子供のころ、見てたなあ。シリーズの中でも、ダントツで一番面白かったん"}, {"k": "spk", "s": "女", "t": "私も見てた。なんと言っても、リーダーの大ファンだったなあ。情熱的で、格好よかった知なタイプのヒーローも好きだったけど、気が弱いのがね。"}, {"k": "spk", "s": "男", "t": "僕は嶄、お調子者のヒーロー。あんなタイプのヒーロー、めったにいないから、面白くて、周りの友達はリーダーか、運動神経抜群で、アクションが格好いいヒーローに憧れてたけどね。"}, {"k": "spk", "s": "女", "t": "私の周りでもそうだったかしいね。"}, {"k": "q", "t": "質問1女の人は4レンジャーで、どの色のヒーローが一番好きでしたか。"}, {"k": "q", "t": "質問2男の人は4レンジャーで、どの色のヒーローが一番好きでしたか。"}]}], "2020-12": [{"head": "市役所で職員3人が話しています。", "lines": [{"k": "spk", "s": "女1", "t": "こ数年、うちの市ても高齢者向け施設て介護をする人早が不足してるでしょう。何か手を打たないと"}, {"k": "spk", "s": "男", "t": "市内の各施設からの報舎を見ると、原因は籬職率が高いことですよね?3年満て辞めていく人が多いのは、やはり体力的にきついからでしょうか。"}, {"k": "spk", "s": "女1", "t": "それもあるでしょうね。まあ、待遇を良くすることが問題解決への近ではあるんだけど、これはそれぞれの施設で決めることだし。"}, {"k": "spk", "s": "女2", "t": "あの、私がいくつかの施設で聞いた話では悩みを打ち明ける場がないのが辛いって言う人も多いようなんです。"}, {"k": "spk", "s": "女1", "t": "そうですか。じゃ、悩みを救い上げるために各設で定期的に管理者と新人職員との論談をするよう籀導しましょうか。"}, {"k": "spk", "s": "女2", "t": "ん一、なんていうか..の嘆がりが欲しいんじゃないでしょうか。1つの葹設に嶄人か1人だけってことも多いので同世代とか同期と話せる場が必要だと思うんです。上司に言いにくいこともあるでしょうし。"}, {"k": "spk", "s": "男", "t": "それって市内のいくっかの施設の職員が集まるってことですか?時間の調整が大変じゃないですか?"}, {"k": "spk", "s": "女2", "t": "えっと、研修という形にすれば、勤霧時間内にみ加できると思います気軽に話し合ってもらうことから始めるというのはどうですか?"}, {"k": "spk", "s": "男", "t": "話すだけで解決するのかな?示髣勗を減する方が必要じゃないでしょうか。介護用ロボットも出てますし。そういうのを導入できるように助金の制度を設けるのはどうですか"}, {"k": "spk", "s": "女1", "t": "ん一、制度を設けるにしても今年度は難しいですね。今回は横の繋がりを重纜する案を具体化していきましょう。問題を改善するために今回はどうすることにしましたか。"}, {"k": "ch", "t": "1.職員の給料の覓しを検罸する"}, {"k": "ch", "t": "2.各設で職員の論談を跫に行う"}, {"k": "ch", "t": "3.他の施設の職員と交流できる研修を行う"}, {"k": "ch", "t": "4.介護用ロボットの導入を支履する"}]}, {"head": "大学で先生の説明を聞いて女の学生と男の学生が話しています。", "lines": [{"k": "spk", "s": "男1", "t": "皆さん、この総合社会学部では2年次から4つの専門コースに分かれます。今日と明日、午後2時から各コースの説明を4つの教室に分かれて行います。1番教室では、経営コースの説明をします。このコースでは経済学や経營学に関する科目を中心に学びます。2番教室は、公兵厳棗コースです。行政に関わる法嵂や棗曇行に関する知識を身に付けるコースです。3番教室は、観光デサインコースです。観光によって地域を活性化する方策を学ぶコースで観業での実習の業もあります。4番教室は、メディア獪顰にコースです。メディアの可能性や紅会葯な影響について学び、情報を社会に伝えていく力を身に付けるコースです。えー、説明を聞いてコース選びの参考にしてください。"}, {"k": "spk", "s": "女", "t": "どれも面白そうだね。私は卒業したら地元に帰って市役所に勤めたりできればいいなと思ってるんた"}, {"k": "spk", "s": "男2", "t": "じゃ、公共政策コースの説明を聞きに行くの?"}, {"k": "spk", "s": "女", "t": "ん一、私の地元は歴史ある町なんだけど、今あんまり知られてないからもっと旅行者が増えて町全体に活気が出るといいなと思ってて。法律よりもそういう角度から学べるコースにしようと思ってる。今日はその説明を聞きに行くつもり。"}, {"k": "spk", "s": "男2", "t": "将来のことしつかり考えてて偉いなあ。僕は最近マスコミの仕事に興味を持ち始めて.."}, {"k": "spk", "s": "女", "t": "え?実家の会社を継ぐんじゃないの?会社経営の勉強するのかと思ってた"}, {"k": "spk", "s": "男2", "t": "まあ、親にはそう言われてるけどね。僕としては自分が興味のあることを勉強してみたいんだ発信カってどんな仕事につくにしても役に立つだろうし、今日はそのコースの説明を聞きに行くよ。"}, {"k": "spk", "s": "女", "t": "そっか。"}, {"k": "q", "t": "質問1:女の学生は今日、何番の教室に説明を聞きに行きますか。3"}, {"k": "q", "t": "質問2:男の学生は今日、何番の教室に説明を聞きに行きますか。4"}]}], "2021-07": [{"head": "会社で上司と社員2人が話しています。", "lines": [{"k": "spk", "s": "女1", "t": "み度開?崔する糞文花理解の研修ですか、誉加者間てのディスカッションの時間が多いですよね。本題に入る前に何か活動を入れたいんですが、アイディアはありませんか"}, {"k": "spk", "s": "女2", "t": "ああ、今回は全国の支社から集まってもらうので初対面の人が多いんですよね。冒頭いけんプ.震かんの自己紹介だけで打ち解けて自由に意見父換するのは難しそうですね。"}, {"k": "spk", "s": "男", "t": "先日、私が佃人に参加した研修では、最初にその場でできる体をしました。体を動かすと緊張も解れて、その後スムーズに意見交換ができました。"}, {"k": "spk", "s": "女1", "t": "リラックスできるのはいいですね。今回の研修会の広さだと動き回ったりはできないでしょうけど・"}, {"k": "spk", "s": "女2", "t": "ん一、楽しんでできるものがいいですよね。クイズをいくつかするのはどうでしょうか。誉加者をチームに分けて、チーム対読にすると盛り上がると思います。"}, {"k": "spk", "s": "男", "t": "いきなりチーム対抗でっていうのは、ちょっと唐突な感じがするかもしれません。それよりも誉加者同士で兵通点を探し合う活動などはどうでしょう。お互いに質問ししつもん,えって、時間内にできるだけたくさん見つけるんです。自己紹介の後の流れとしても自然だと思いますkゆし"}, {"k": "spk", "s": "女1", "t": "相手を知るっていう意味では研修の王旨にも沿ってますね。クイズは王旨に沿ったないようし内容を準備するのは時間がかかりそうですね。"}, {"k": "spk", "s": "女2", "t": "そうですね。あとは参加者全員の名前をその場で覚えて言うっていうゲームをやったことがあります。これも盛り主がりますよ。"}, {"k": "spk", "s": "女1", "t": "そうですね。ただ、やつばり単に緊張を解すとか、り主がるっていうものより、研蓚内容に繋がるものにしましょう。研修会の冒頭でどんな活動をすることにしましたか。"}, {"k": "ch", "t": "1.リラックスできる体操"}, {"k": "ch", "t": "2.チーム対読のクイズ。"}, {"k": "ch", "t": "3.誉笳暑筒午の箕をす活動。"}, {"k": "ch", "t": "4.参加者の名前を覚えるゲーム。"}]}, {"head": "テレビのニュースを聞いて女の人と男の人が話しています。", "lines": [{"k": "spk", "s": "男1", "t": "みどり市では来月2日、市長選が行われます。今回の立候補者は4名です。まず、現職の田中ゆうじ氏。再選された場合は、高齢者の介護事業に引き続き力を注ぎたいとのことです。次に山田えり子氏。スポーツ環境の整備、心理相室の開設など市民の心身の健康増進を図る考えです。続いて鈴木はるみ氏葆薗の整備、子供の医療費無料化を実現し、少字化対に取り組むとのことです。最後に石井かずお氏。郊外の住宅地と市街地を繕ぶ公共交通支援事業を実施し、生活しやすい町づくりを進めるとの考えです。"}, {"k": "spk", "s": "女", "t": "市長選、もうすぐだね。私、昨日駅前で候補者の演説を聞いたよ。あの市民の健康のための事業を進めるっていう人。話が具体て意味もよく伝わってきたよ。老朽花した運動塲の整備とか、カウンセリングの窓口の設置とかせい盞"}, {"k": "spk", "s": "男2", "t": "へえー、直接聞くとよくわかるってことあるよね。"}, {"k": "spk", "s": "女", "t": "他の候補者の話も聞いてみたいと思ってるんた葆簡の棗が気になってて。"}, {"k": "spk", "s": "男2", "t": "そっか。僕は祖母が町から少し離れた所に住んてるんだけど、市街のスーパーや病院に車でり迎えしてほしいって頼まれることが多くて。祖母がよく、バスがないって不満言ってる。だからその政策を掲げる人を持したいんだ"}, {"k": "spk", "s": "女", "t": "そうなんだ。高齢者人口も多くなってきてるからいろんな支が必要だよね。"}, {"k": "q", "t": "質問1女の人は昨日、どの候補者の演説を聞いたと言っていますか。解答2"}, {"k": "q", "t": "質問2男の人はどの候補者の政策に期待していると言っていますか。解答4"}]}], "2021-12": [{"head": "会社で上司と社員2人が話しています。", "lines": [{"k": "spk", "s": "男1", "t": "今度社員の健康のために会社として対策を立てることになってね。来週の会議に案を一つ持っていかないといけないんだけど、何かいいアイテアあるかな?"}, {"k": "spk", "s": "女", "t": "そうですね。パソコンの前に座りつばなしって人が多いのでエレベーターを使用しないとか決めるのはどうでしょうか。"}, {"k": "spk", "s": "男1", "t": "階段を使うってことだね。うーん"}, {"k": "spk", "s": "男2", "t": "私は普段野菜不足になりがちなんです。うちの社員食堂栄養バランスがいいから、夕食も会社で食べられるといいなあと前から思っていて、社員食堂の営業時間を延長するのはどうでしょうか?"}, {"k": "spk", "s": "男1", "t": "あー、夜8時頃まで開いている会社もあるらしいね。"}, {"k": "spk", "s": "男2", "t": "あと、この前ニュースで見たんですけど、最近は朝パンやおにぎりをオフィスに置いている会社も増えてるみたいなので。そういうのを取り入れるのもいいと思いますが、朝何も食べないでくる人もいるでしょうし。"}, {"k": "spk", "s": "男1", "t": "うーん、パンやおにぎりで野菜不足が解消されるかなあ。それにうちの会社は勤務時間が社員の自由裁量になってるけど、早く来る人より遅い時間にずらしてる人の方が多いね。夜の方が利用したい人が多いかもね"}, {"k": "spk", "s": "女", "t": "あのう、会社でウォーキング大会を開催するっていうのはどうでしょうか?やつばり体を動かすことも大切ですよ。イベントの開催で健康に対する意識も高まると思います。"}, {"k": "spk", "s": "男1", "t": "確かにね。まあ、そういうイベントってどうしても休日になっちゃうから、ちょっとね、うーん、色々意見を出してくれてありがとう。階段を使うのも運動になって良さそうだけど、強制はてきないからねー。さっきのニーズが高そうで、効果もありそうな案を会議で提案してみるよ。上司は来週の会議でどんな提案をすることにしましたか。1エレベーターの使用を制限すること。2食堂の営業時間を延長すること。3オフィスで朝食を提供すること。4ウォーキング大会を開催すること。"}]}, {"head": "テレビである市の市長が話しています。", "lines": [{"k": "text", "t": "我が大場市の市営地下鉄は最近旅行者の利用が増えております。より快適に利用していただけるよう、地下鉄の駅に関して四つの改良計画案を検討中です。案ーは出入り口や駅構内の案内表示を分かりやすくすることです。表示が小さくて目立たない矢印の向きが分かりにくいといった点を改善します。案二はバリアフリーの拡充て、まずは全駅でエレべーターの設置を検討中です。続いて、案三はトイレの整備です。利用しやすい場所に新たに設置することを検討しています。最後に、案四は主要駅の案内所の充実です。地下鉄の乗り換え案内だけでなく、地域の観光情報なども提供できるよう準備を進めているところです。"}, {"k": "spk", "s": "男", "t": "確かに最近駅でよく旅行者を見かけるようになったよね。"}, {"k": "spk", "s": "女", "t": "うん、私も最近よく大きいスーツケースを持った人に乗り方とか聞かれる。案内所って大きい駅にしかないからね"}, {"k": "spk", "s": "男", "t": "うん、地下鉄の駅って外の様子が見えないし、案内表示に頼る部分が大きいよね。分かりにくくて困ること僕も結構あるよ。まずはそれを改善してくれたら旅行者だけじゃなくてみんな助かると思う"}, {"k": "spk", "s": "女", "t": "そうだね。私は出張の時とかスーツケース持って移動することあるけど、最寄り駅にエレべーターがなくて大変なんだよね。だからそっちの方を早く進めてほしいと思う。トイレは、まあ数を増やすことも大事だけど、気持ちよく使えるように清潔にしておいてほしいよね"}, {"k": "spk", "s": "男", "t": "そうだね。"}, {"k": "q", "t": "質問1男の人はどの案を優先してほしいと言っていますか。解答1"}, {"k": "q", "t": "質問2女の人はどの案を優先してほしいと言っていますか。解答2"}]}], "2022-07": [{"head": "会社で部長と社員2人が話しています。", "lines": [{"k": "spk", "s": "女1", "t": "毎月、部内会議をやってるけど、会議に時間を取られ過ぎているという声がありますね。"}, {"k": "q", "t": "やはりそう思いますか"}, {"k": "spk", "s": "男", "t": "そうですね。会議が長引くことも多いですし、議題をもう少し絞れないんでしょうか。"}, {"k": "q", "t": "みんなで話さなくていいことも多いんじゃないですか。"}, {"k": "spk", "s": "女2", "t": "でも、減らし過ぎると、この部の課題が共有できなくなって、チームとしての仕事が難しくなると思います。"}, {"k": "spk", "s": "女1", "t": "ええ、情報共有は私も意識しています。議題自体は毎回適切に設定されていると思いますよ。"}, {"k": "spk", "s": "男", "t": "じゃあ、会議の予定の終了時間になったら、必ず終わることを徹底するというのはどうですか。"}, {"k": "spk", "s": "女2", "t": "それ、他の部で前にやってましたが、みんな時間を気にして、意見が出にくくなったそうです。"}, {"k": "spk", "s": "女1", "t": "それだと、意味がないですね。"}, {"k": "spk", "s": "女2", "t": "会議の資料を事前に送っていただいていますが、資料に目を通すだけじゃなくて、意見や提案があれば、会議の出席者に前もって知らせておくというのはどうですか。どんな意見があるか共有されていれば、会議で話し合う時間が短縮されると思います。"}, {"k": "spk", "s": "女1", "t": "なるほど。"}, {"k": "spk", "s": "男", "t": "会議の前に意見を取りまとめないといけなくなりますね。"}, {"k": "spk", "s": "女1", "t": "そこまでしなくても意見があれば出席者全員にメールで送っておいてもらえれば十分だと思います。じゃあ、次の会議からやってみましょう。この部では新たに何をすることにしましたか?"}, {"k": "ch", "t": "1.会議の議題を絞る"}, {"k": "ch", "t": "2.会議の終了時間を守る"}, {"k": "ch", "t": "3.事前に出席者に資料を送る"}, {"k": "ch", "t": "4.出席者の間で事前に意見を共有する"}]}, {"head": "シンポジウムで司会者が話しています。その後、男の人と女の人が話しています。", "lines": [{"k": "spk", "s": "女1", "t": "え~、第一部では「一生健康でいるために」というテーマで4人の先生方にお話を伺いました。第二部では、4つの部屋に分かれ、それぞれの先生を囲んで直接意見交換をしていただきます。ご興味に合わせて各部屋に移動してください。まず1番の部屋は、予防医学の見地から睡眠や栄養について紹介していただいた川西先生です。2番の部屋は、高齢者の心の問題とその対応についてお話しされた杉山先生です。3番の部屋は、丈夫な身体を作る体操についてお話しくださったスポーットレーナーの高橋先生です。4番の部屋は、病気の治療法に関する最新情報についてお話しくださった池田先生です。では、10分後に開始します。"}, {"k": "spk", "s": "男", "t": "第一部、勉強になりましたね。私、最近、スポーツジムに通い始めたんですけど、頑張て続けようと思いましたよ。"}, {"k": "q", "t": ":女、2:じゃあ、第二部はスポーットレーナーの先生の所に行くんですか。"}, {"k": "spk", "s": "男", "t": "ん~実は最近よく母が年をとってできないことが増えてきたって落ち込んでて。だから、母を少しでも元気づける方法を聞きたいと思ってるんです。"}, {"k": "spk", "s": "女2", "t": "そうですか。いいアドバイスが聞けるといいですね。私は病気を未然に防ぐ方法について話を聞こうと思ってます。最近、頭痛がひどくて病院に行って検査を受けたんです。"}, {"k": "spk", "s": "男", "t": "えっ~そうなんですか。"}, {"k": "spk", "s": "女2", "t": "結局、特に何も悪い所は見つからなくて..寝不足が続いて疲れがたまってただけみたいなんですけど。でもあらためて睡眠とか、日々の生活習慣って大事だなと思うようになって.....。だからその話を聞きに行こうと思ってます。"}, {"k": "q", "t": "質問1:男の人はどの部屋へ行きますか。2"}, {"k": "q", "t": "質問2:女の人はどの部屋に行きますか。1"}]}], "2022-12": [{"head": "地域の日本語教室でスタッフ3人が話しています。", "lines": [{"k": "spk", "s": "男性A", "t": "教室で日本語を教えるボランティアがなかなか増えませんね市の広報誌に定期的にボランティア募集の案内を載せてるんですが。"}, {"k": "spk", "s": "女性", "t": "少し前に一人見学に来ましたけど、入ってもらえなかったんですよね。"}, {"k": "spk", "s": "男性A", "t": "その日はいつもよりさらにボランティアの数が少なかったんです。ホランティアー人でいろんなレベルの学習者5人くらいに対応をしてたのでその様子を見て、自分には難しそうって尻込みしちゃったみたいです。"}, {"k": "spk", "s": "男性B", "t": "じゃあ、教え方のマニュアルでも作りましょうか~"}, {"k": "spk", "s": "女性", "t": "マニュアルを作って対応できる問題じゃないですよね。学習者のレベルも目的もいろいろだから。"}, {"k": "spk", "s": "男性A", "t": "そうですねえ"}, {"k": "spk", "s": "男性B", "t": "じゃあ、ボランティアの種類を分けて募集するのはどうですか~日本語を教えるボランティアと会話を教えるボランティア。会話のボランティアならやってみようと思う人もいるかもしれませんよ。"}, {"k": "spk", "s": "男性A", "t": "どちらかというと、教えられる人に来てもらえるといいんですけどねえ。"}, {"k": "spk", "s": "女性", "t": "去年まで頑張ってくれてた大学生のボランティアが就職を機に何人か抜けちゃったのが残念ですね。言語学や教育学を学んでたから教え方も上手でしたし。市内の大学に募集のポスターを貼らせてもらいましょうか~"}, {"k": "spk", "s": "男性B", "t": "大学生だと、また就職とかで辞めちゃうんじゃないですか~"}, {"k": "spk", "s": "男性A", "t": "まあ、まずは応募してもらわないとね。市の広報誌よりも目に留まりそうだし。やってみましょうか。今回はボランティアの種類は分けずに募集してみましょう。"}, {"k": "q", "t": "問いボランティアを増やすために何をすることにしましたか?(正解:4)"}, {"k": "ch", "t": "1.市の広報誌で募集する回数を増やす。"}, {"k": "ch", "t": "2.教え方のマニュアルを作る"}, {"k": "ch", "t": "3.ボランティアの種類を分けて募集する"}, {"k": "ch", "t": "4.市内の大学に募集のポスターを貼る。"}]}, {"head": "ある町の農業に関する説明会で役所の人の説明を聞いた後、男の人と女の人が話しています。", "lines": [{"k": "spk", "s": "役所の人", "t": "この町で力を入れている4つの農作物をご紹介します。説明の後で各農作物について個別の相談をお受けします。まずは、高原の涼しい気候を利用したキャベッ栽培。種まきから収穫まで手がかかりますが、近年産地として評価されるようになり、収益性が高いのも特徴です。次に、キノコとイチゴ。どちらもハウス栽培で管理は大変ですが、田んぼや畑よりはカ仕事が少ないです。キノコは栄養が豊富で健康にいいということで安定した需要があります。イチゴは観光客向けの収穫体験ツアーにも協力していて、農園の一部をカフェにしているところもあります。最後は、お米この町の米は味が良いことで昔から知られています。設備投資は大掛かりになりますが、農家と行政が一体となって美味しい米作りに取り組んでいます。"}, {"k": "spk", "s": "男の人", "t": "いろいろあるんですねえ。どちらからいらしたんですか~"}, {"k": "spk", "s": "女の人", "t": "東京からです。農業に関わりたいなと思って来たんです。体力にそう自信があるわけじゃないんですねどね。"}, {"k": "spk", "s": "男の人", "t": "カ仕事が比較的少ないっていうのもあるみたいですね"}, {"k": "spk", "s": "女の人", "t": "ええ。私、人と接するのも好きなので、農作業だけじゃなくお客さんの対応もするのが向いてるかなと思って、その説明を聞きたいと思ってます。"}, {"k": "spk", "s": "男の人", "t": "そうですか。私は農業で生計を立てていきたいのでやつばり収入を重視しますね。"}, {"k": "spk", "s": "女の人", "t": "そうですよね。"}, {"k": "spk", "s": "男の人", "t": "実は私、この町出身なので、伝統的に作られてきたものにも思い入れがあるんですけど...それより、新しい地域の名産として評価され始めたものをこれからもっと売り出す方に興味があって、その説明を聞きに行こうと思ってます。"}, {"k": "q", "t": "質問1:女の人はどの農作物の説明を聞きたいと言っていますか?(正解:3)"}, {"k": "q", "t": "質問2:男の人はどの農作物の説明を聞きたいと言っていますか?(正解:1)"}]}], "2023-07": [{"head": "レストランで経営者と従業員2人が話しています。", "lines": [{"k": "text", "t": "こうとう"}, {"k": "spk", "s": "男1", "t": "ここ最近野菜の値段が高騰していて、サラダバーを続けていくのは厳しいんだ。二人はどう思う?"}, {"k": "spk", "s": "女", "t": "そうですね。今サラダバーで新鮮野菜のグリーンバーなどを出していますが、それを減らして比較的価格が安定している冷凍野菜や豆などを使った新しいサラダを出せば話題性もあると思います。JLPT・N1・07/2023"}, {"k": "spk", "s": "男2", "t": "実際のサラダメニューは調理の人に考えてもらう必要がありますよね。う~ん、野菜の値段は不安定ですから、ここは思い切ってサラダバーを止めることを考えてもいいかもしれません。"}, {"k": "spk", "s": "女", "t": "でもランチは特にサラダバーを目当てに来店されるお客様がほとんどですから無くすべきではないと思います。無くしてしまうとお客様が減ると思います。サラダバーの値上げは難しいですか?値上げしてでも継続していくべきだと思いますが。"}, {"k": "spk", "s": "男1", "t": "私もできれば続けていきたいとは思うよ。ただこのご時世に値上げをするというのねぇ。"}, {"k": "spk", "s": "男2", "t": "でしたら、サラダバーだけでなくメニュー全体を少しずつ値上げするというのはどうでしょうか?それなら一つ一つは少しの値上げで済むと思いますが。"}, {"k": "spk", "s": "男1", "t": "うちはただでさえ競合店より高めの価格帯でやっているから、メニュー全体の値上げは..."}, {"k": "spk", "s": "女", "t": "客離れにつながりますよね。"}, {"k": "spk", "s": "男1", "t": "それは極力避けたいね。うーん、じゃあ調理の人に新しいメニューを考えてもらうことにしよう。大変な時こそ工夫して乗り切るのが大事だね。問このレストランではどうすることにしましたか?1 サラダバーに出すサラダを一部変える。2 サラダバーを廃止する。3 サラダバーを値上げする。4 メニュー全体を値上げする。"}]}, {"head": "テレビで書店の紹介を聞いて男の学生と女の学生が話しています。", "lines": [{"k": "spk", "s": "テレビ", "t": "今日は「本の町」と言われる東町をご紹介します。ホク東町には50店近い書店が並んでいますが、その中から個性的な書店を4つご紹介します。まずは島田書店、動物や植物に関する本を扱う店です。200年も前にヨーロッパで印刷された貴重な図鑑もあるそうですよ。森山書店は児童向けの書籍を扱う専門店です。メイや児童文学だけでなく、メイ海外の作品も充実しています。南ブックスは地図の専門店です。古い地図も扱っていて江戸時代の街並みを描いた歴史的に貴重な資料を最近入手したそうです。そして北の輪ブックスは芸術、ファッション、写真などアートに関する書籍を販売していて、とりわけ海外の書籍の品ぞろえは抜群です。"}, {"k": "spk", "s": "男", "t": "東町、噂には聞いてたけど、いろんな本屋があるんだね。僕探してる本があるんだけど、今紹介されてた店に行けば見つかるかも。今度の週末、一緒に行かない?"}, {"k": "spk", "s": "女", "t": "いいよ。鈴木さんが探してる本ってアートの本?鈴木さんたくさん持ってるよね?ジョジョ。"}, {"k": "spk", "s": "男", "t": "ああ、今探してるのは草花の専門書なんだ。まだ写真がなかった時代に作られたもので、草花の絵がアートとしても評価されてるんだよ。古い図鑑があるって言ってたしその店に行ってみたいと思うね。JLPT・N1・07/2023"}, {"k": "spk", "s": "女", "t": "そうなんだ。私も行きたい店があるんだけど、いい?つい最近児童図書を見に東町まで行ったんだけど、その時は地図の店に江戸時代の資料が入ったなんて知らなかったからさっきの紹介聞いてそっちにも寄ればよかったって思ったんだ。"}, {"k": "spk", "s": "男の学生", "t": "そうなんだ?いいよ。"}, {"k": "q", "t": "質問1男の学生はどの店に行きたいと言っていますか?"}, {"k": "text", "t": "1「島田書店」"}, {"k": "q", "t": "質問2女の学生はどの店に行きたいと言っていますか?"}, {"k": "text", "t": "3「南ブックス」"}]}], "2023-12": [{"head": "市役所で係の人3人が市で開く文化講座について話しています。", "lines": [{"k": "spk", "s": "男1", "t": "市の文化講座だけど、来年度は新しいクラスを一つ開設するんだったよね?どうなってる?"}, {"k": "spk", "s": "男2", "t": "はい。私は参加者が楽しみながら知的好奇心を満たせるものがいいと考えています。例えば、今年度高齢者に人気の「古代史を学ぶ」のようなものですね。今度は近代史に焦点を当てて、「近代史を学ぶ」はいかがでしょうか?"}, {"k": "spk", "s": "女", "t": "それだと、また高齢者の方中心になってしまいませんか?私は、今度はもっと幅広い世代に来ていただきたいと思って「町の産業を知ろう」という講座を考えてみました。子供と親がいろいろな職業を疑似体験して、身近なことから地元の産業について一緒に学んでいくものです。"}, {"k": "spk", "s": "男1", "t": "なるほど、それなら多くの人に来てもらえそうでいいね。"}, {"k": "spk", "s": "男2", "t": "でも、子供とその親だったら、そんなに幅広い年代ってわけじゃないですよね?もし2年続けて歴史的なものをするのがよくないなら、「身近な社会問題を考えよう」というのはどうですか?身の回りで実際に起こっているけれど、普段あまり気づかないような問題についてディスカッションするんです。"}, {"k": "spk", "s": "女", "t": "うーん、そういうテーマに関心があっても、ディスカッションとなると人は集まらないと思いますけど・・・。さっきの私の案なら子供に付き添いながら意外と知らなかったことをさりげなく学べていいと思います。"}, {"k": "spk", "s": "男1", "t": "確かに。別に親子じゃなくて、高齢の方がお孫さんも連れてきてもいいわけだしね。よし、それでいこう。来年度はどの講座を開くことになりましたか。正解:3"}, {"k": "ch", "t": "1.古代史を学ぶ"}, {"k": "ch", "t": "2.近代史を学ぶ"}, {"k": "ch", "t": "3.町の産業を知ろう"}, {"k": "ch", "t": "4.身近な社会問題を考えよう"}]}, {"head": "ラジオで梨の生産者が話しています。それを聞いて夫婦が話しています。", "lines": [{"k": "spk", "s": "女", "t": "山川市は梨の栽培が盛んでいろいろな品種を育てています。まず「光」という品種は7月から収穫され始め、8月に最盛期を迎えます。甘みが強いのが特徴です。続いて、「月」は9月に入ると店頭に並び始めます。みずみずしさが人気でさっぱりとした味わいです。えー、「星空」はかなり大きめの梨で、10月から11月まで出荷されます。味はもちろん、見栄えの良さから贈答品としてもよく利用されています。そして、「朝日」ですが、11月の終わりから収穫される品種です。保存がきき、お正月にも楽しめるというので人気が出てきました。どの品種も山川市農業組合のホームページから通販でご予約いただけますのでぜひご利用ください。"}, {"k": "spk", "s": "男", "t": "へぇー、梨ってけっこう長期間楽しめるんだね。お互い好きなの一つずつ選んで予約しようよ。"}, {"k": "spk", "s": "女2", "t": "いいね。果物を暑い季節に冷やして食べるの最高だよね。"}, {"k": "spk", "s": "男", "t": "それなら「みずみずしい」って言うのがいいんじゃない?水分が多そうで喉を潤してくれそうだよ。"}, {"k": "spk", "s": "女2", "t": "さっぱりした味っていう梨?うーん、私は甘みが強いって言ってたのがいいな。一つはそれにしようよ。"}, {"k": "spk", "s": "男", "t": "そっか、いいよ。僕はお正月に食べられるっていうのもいいけど。うーん、でも見た目にも立派っていうのがやっぱりいいな。贈り物にするようなものを自分で注文するって何だか贅沢でいいよね。"}, {"k": "spk", "s": "女2", "t": "あ、そうだね。待ち遠しいなぁ。"}, {"k": "q", "t": "質問1:女の人はどの梨を選びましたか。正解:1"}, {"k": "q", "t": "質問2:男の人はどの梨を選びましたか。正解:3"}]}], "2024-07": [{"head": "大学の新聞部で部長と部員2人が話しています。", "lines": [{"k": "spk", "s": "女1", "t": "来月発行する新聞、野球部の地区大会に向けて特集を1ページ組むことになってるけど、そろそろ内容を練らなきやね。どうしようか~"}, {"k": "spk", "s": "男", "t": "地区大会、2か月後に迫ってますよね。以前、野球部を取り上げた時はキャプテンの意気込みやチームの仕上がり具合を中心に取材しましたが"}, {"k": "spk", "s": "女2", "t": "去年は準優勝に終わったので、今年こそって学内の期待も高まってますよね。"}, {"k": "spk", "s": "女1", "t": "そうだね。何がいいかな~前やったのと同じようなのはしたくないし。"}, {"k": "spk", "s": "男", "t": "ライバルチームの練習の様子を取材してはどうですか~去年の優勝校とは今年も間違いなく顔を合わせることになると思うんですけど・・"}, {"k": "spk", "s": "女1", "t": "うん、他にはどうかな~"}, {"k": "spk", "s": "女2", "t": "「選手たちの素顔に迫る」っていうのはどうでしょう~主要な選手2、3人、例えば、投手やキャプテンに密着して1日を追うんです。練習以外の時間、どんな風に過ごしてるかとか、読んだ人が選手を身近に感じられるような情報がいいと思うんです。"}, {"k": "spk", "s": "女1", "t": "そうだね。"}, {"k": "spk", "s": "女2", "t": "それか、レキュラー選手を全員紹介するっていうのもいいと思います。選手の守備位置だけじゃなく、趣味とか好きな食べ物とか、顔写真と一緒に載せるんです。読者がお気に入りの選手を見つけられるように"}, {"k": "spk", "s": "男", "t": "僕は対戦相手のことも情報としてあった方がいと思いますけどその方が応援に行った時に試合を見てて面白いと思うんです。"}, {"k": "spk", "s": "女1", "t": "そうだね。でも実際どのチームと対戦することになるかはまだわからないから今、他のチームのことを取り上げても読者にはピンと来ないかもしれないね。試合に出る選手全員っていうと紙面が限られてるし・。さっきの密着取材の案、面白いんじゃないかなうん、今回は何人かに絞って取材することにしよう。新聞に載せる野球部の特集は何を書くことにしましたか。1大会に向けてのキャプテンの意気込み2ライバルチームの練習の様子。3主要な選手の1日の過ごし方。4レギュラー選手全員の紹介。"}]}, {"head": "ラジオでアナウンサーが夏の夜空を楽しむ講座について話しています。", "lines": [{"k": "spk", "s": "女1", "t": "山川市にある科学館では来月、夏の夜空を楽しむための4つの講座を開くそうです。講座1番はオリジナルの星座作り。星空の写真を見ながら自分たちで星を繋ぎ合わせて自由に形を作り、名前を付けたり星座の物語を作ったりします。講座2番は星空の撮影。露出時間を長く設定できるカメラと二脚さえあれば、意外と簡単に星空を撮影できるそうですよ。講座3番は流れ星の観察です。来月中旬は深夜の夜空に星が降り注ぐ数年に一度の貴重な機会です。ゆっくり眺めながら星に願い事をするのも素敵ですね。最後、講座4番は地球を回る国際宇宙ステーションの観察です。国際宇宙ステーションは、実は日没後のある時間、ある方角に肉眼で見ることができるんだそうですよ。"}, {"k": "spk", "s": "男", "t": "どれか一緒に参加しようよ。参加したいのあった~"}, {"k": "spk", "s": "女2", "t": "うーん、星座を作るよりは実際に見る方がいいかな。あと、星空の写真は自分でも時々撮るから違うのがいいな"}, {"k": "spk", "s": "男", "t": "すごいね。国際宇宙ステーションも撮ったことある~"}, {"k": "spk", "s": "女2", "t": "うううん、まだ見たこともないの。うーん、だからこの講座に参加して見てみたいな。"}, {"k": "spk", "s": "男", "t": "そっか。うーん、でもそっちより星をメインて見るやつの方がいいな。"}, {"k": "spk", "s": "女2", "t": "そうだね。めったにないチャンスだもんね。それにしよう!"}, {"k": "q", "t": "質問1女の人が最初に参加してみたいと思ったのはどの講座ですか。解答4"}, {"k": "q", "t": "質問22人はどの講座に参加することにしましたか。解答3"}]}], "2024-12": [{"head": "書店で店長と店員2人が話しています。", "lines": [{"k": "spk", "s": "男1", "t": "最近お客さんが減って売り上げが落ちてるんだよね。駅の近くに新しい書店もできたし、何か売り上げを回復する良い案はないかな~"}, {"k": "spk", "s": "女", "t": "今、全国の売り上げランキングで上位に入ってる本を入り口近くに置いてますけど、もっとお客様の目に留まりやすいようにレジに近いところに置くのはどうですか~"}, {"k": "spk", "s": "男1", "t": "うちは近くにデサイン関係の会社が多いからか、以前からデザイン関連の本がよく売れてますよね。それに店員の推薦文を書いたカードをつけてもっと目立たせたらどうですか~前にもやったことあるけど手間がかかるんだよね。"}, {"k": "spk", "s": "女", "t": "それか雑誌をより充実させるのはどうでしょうか。最近は種類も増えているので。雑誌が揃っていればそれを目当てに来てくれる新しいお客さんも増えるかもしれません。"}, {"k": "spk", "s": "男1", "t": "そうだね。"}, {"k": "spk", "s": "男2", "t": "私は以前からのお客様を引き続きターゲットにした方がいいと思うんです。写真集とか雑誌とか種類に関わらず、デザインに関連する本を1ヶ所にまとめたコーナーを作るのはどうですか~それがうちの強みになると思うんです。"}, {"k": "spk", "s": "女", "t": "新しいコーナーですか~場所はどうするんですか~"}, {"k": "spk", "s": "男1", "t": "うーん。じゃ、ソファーが置いてある閲覧スペースに棚を増やしてそこに集めようか。1ヶ所にまとめてあるほうがアピールになるね。推薦文のカードをつけるのは様子を見てからに書店の売り上げを回復するためにまずどうすることにしましたか。1売れている本をレジの近くに置く2デサイン関連の本に推薦文のカードをつける3雑誌のコーナーを広くする4デザイン関連の本のコーナーを作る"}]}, {"head": "テレビを見ながら夫婦が話しています。", "lines": [{"k": "spk", "s": "女1", "t": "最近一般の人が製品の工場を見学できるところがあります。今日はその中から4つご紹介します。まずヒガシャの工場。こちらではカップスープの製造工程を見学した後、カップに好きな具と粉末のスープを組み合わせて入れて、オリジナルのカップスープを作って持って帰れます。次はニシマル、牛乳工場です。こちらでは製造管理のため、味覚の専門家が製品の風味を自分の舌で確認するシステムを取り入れています。見学の際、味覚の専門家から実際の牛乳の検査方法などについて聞くことができます。ミナミはサッカーポールの工場です。ポール用の皮が次第に立体的になっていく様子に目を見張ります。小さなポールに色付けする作業を体験できて、できたものはお土産に持って帰れます。最後はおもちやメーカーのキタヤ。この工場では車や電車のおもちやを作る過程が見学できます。こでしか入手できないオリジナル商品が購入可能なのも人気の理由なんだそうですよ。"}, {"k": "spk", "s": "女2", "t": "へ一、面白そう。今度子供連れて行ってみない~"}, {"k": "spk", "s": "男", "t": "うん、いいね。僕は機械化されてる工場でも最終的には人間の舌で確認しているっていうの興味深かかったけど、でもまあ、子供も一緒だから実際に作れるとこのほうがいいな。"}, {"k": "spk", "s": "女2", "t": "あ、ポールね。"}, {"k": "spk", "s": "男", "t": "あ、そっちじゃなくて。いつも飲んでるの、ちょっと違う味にできるなんて面白そう。行くならそこがいいな。君はどこがいいと思う~リョウタが好きな乗り物~"}, {"k": "spk", "s": "女2", "t": "うーん、そこはオリジナル商品をねだられて買う羽目になりそう。お土産をもらえるところならその心配がないからいいよね。うちに帰ってから遊べるし。"}, {"k": "spk", "s": "男", "t": "うん。じゃ、リョウタにも聞いてから決めよう。"}, {"k": "q", "t": "質問1男の人はどの工場に行きたいと言ってますか。解答1"}, {"k": "q", "t": "質問2女の人はどの工場に行きたいと言ってますか。解答3"}]}], "2025-07": [{"head": "地域の国際交流サークルのリーダーとメンバー2人が話しています。", "lines": [{"k": "spk", "s": "女1", "t": "毎年恒例の夏の若葉山ハイキング、いつも行っている5番コースが今年は整備中で使えないんだよね。他に4つコースがあるけど、今年はどのコースにしようか。2人は何度も行ってるから詳しいよね?"}, {"k": "spk", "s": "女2", "t": "参加者はいつも20人ぐらいですよね?今年も同じぐらいでしょうか。"}, {"k": "spk", "s": "女1", "t": "うん、初めて参加する人もいると思うからそれも考慮しないとね。"}, {"k": "spk", "s": "女2", "t": "いつものコースが使えないなら、1番コースがいいんじゃないんですか?道の幅が広いし、傾斜も比較的広いから初めての人にもいいと思います。"}, {"k": "spk", "s": "男", "t": "あそこは歩きやすくて人気のコースだから混雑することが多いですよ。"}, {"k": "spk", "s": "女2", "t": "じゃ、2番コースはどうですか?所要時間が長いから人はあまり多くないですよね?道もなだらかだし、みんなでおしゃべりしながら歩けると思います。"}, {"k": "spk", "s": "男", "t": "うーん、僕は渓流に沿った3番コースが景色が楽しめていいと思うんですけど、小さい滝も見られますし、途中、急なところはありますが。"}, {"k": "spk", "s": "女1", "t": "そっか。"}, {"k": "spk", "s": "男", "t": "それか4番コースはどうでしょうか。道があまり整備されてなくて歩きにくいですが、きれいな林が続いてて気持ちがいいですよ。"}, {"k": "spk", "s": "女2", "t": "初めて参加する人も多いから歩きやすいコースがいいかと。"}, {"k": "spk", "s": "女1", "t": "そうだね。今回は交流が目的だからみんなでゆっくり話しながら歩けるコースで込まないほうにしよう。景色のいいコースは次の機会に行けたらいいね。"}, {"k": "q", "t": "今年のハイキングはどのコースにしますか。"}, {"k": "text", "t": "1番コース2番コース3番コース4番コース"}]}, {"head": "香水を作るワークショップで講師の話を聞いた後、女の人と男の人が話しています。", "lines": [{"k": "spk", "s": "女1", "t": "本日は皆さんに香水作りを体験していただきます。前のテーブルに先ほど嗅いでいただいた香水が4種類置いてあります。この中から一つ、好きな香りを選んで作っていただきますが、改めて各香水についてご説明します。1番の香水はレモンのような果物系の香水です。どなたにも好まれる香りです。2番は夏にぴったりの爽やかなハーブの香りです。つけているとスッキリとした気分になれます。3番はスパイスのようなような刺激的で独特な香りです。4番は甘い花の香りの香水です。優しい印象を演出してくれます。では、選んだからこちらに材料を取りに来てください。"}, {"k": "spk", "s": "女2", "t": "どれもいい香りだったね。どれにする?"}, {"k": "spk", "s": "男", "t": "うん、スパイスみたいな香りかフルーツの香りで迷うな。でもフルーツの香りが好きで普段から使っているんだよね。それにしようかな。"}, {"k": "spk", "s": "女2", "t": "私は気分がスッキリするのにする。甘い香りのも良かったけど、同じようなの持ってるから。"}, {"k": "spk", "s": "男", "t": "そっか、やっぱり僕もいつも使っているのと違うほうにするよ。"}, {"k": "spk", "s": "女2", "t": "じゃ、材料をもらいに行こう。"}, {"k": "q", "t": "質問1男の人は何番の香水にすると言っていますか。"}, {"k": "text", "t": "解答3"}, {"k": "q", "t": "質問2 女の人は何番の香水にすると言っていますか。"}, {"k": "text", "t": "解答2"}]}], "2025-12": [{"head": "スーパーで店長と店員2人が話しています。", "lines": [{"k": "spk", "s": "店長", "t": "食品の廃棄が問題になっているけど、うちの店でもどうしても売れずに廃棄するものが出てしまっているよね。今も消費期限が近いものは割引してるけど、もっといい方法ないかな?"}, {"k": "spk", "s": "女", "t": "売り場に「消費期限が近い物から購入してください」っていうポスターを貼ってますけどね。もっと増やしましょうか?"}, {"k": "spk", "s": "店長", "t": "そうだね。"}, {"k": "spk", "s": "男", "t": "売れ残りそうな食品を引き取って福祉活動に役立てている団体もあるって聞きましたよ。そういう団体に食品を提供するとか。店側でできることを考えた方がいいと思います。"}, {"k": "spk", "s": "店長", "t": "うーん、いい案だと思うけど、それだと提供できる品物は限られるから、結局廃棄するものはあまり減らないよね。"}, {"k": "spk", "s": "女", "t": "消費期限が近い商品にくじ引きのシールを貼って、当たりが出たらその商品が無料になるっていうのはどうでしょう?お客様に喜んでもらえると思います。"}, {"k": "spk", "s": "店長", "t": "ああ、前にイベントで使ったシールの在庫があるから、あれを活用できそうだね。"}, {"k": "spk", "s": "男", "t": "楽しそうですね。あとは仕入れですが、今は経験のあるスタッフが売れ行きを予測して仕入れを調整してますが、需要を予測するソフトウェアを導入するのはどうですか?もっと正確に予測できるから廃棄を減らせると思います。"}, {"k": "spk", "s": "女", "t": "ソフトウェアは利用料がかかりますよね。"}, {"k": "spk", "s": "店長", "t": "そうだね、経験がなくても仕入れ量が調整できるように考えないといけないけど、コストを考えるね。うん、じゃ、お客様に喜んでもらえそうなことから始めよう。それであまり効果がなかったらソフトウェアの利用を検討しよう。ゆくゆくは福祉活動にも協力できるといいね。"}, {"k": "q", "t": "問い食品の廃棄を減らすためにまず何をすることにしましたか。"}, {"k": "text", "t": "売り場のポスターを増やす福祉団体に食品を提供する商品にくじ引きのシールを貼る需要を予測するソフトウェアを利用する"}]}, {"head": "ラジオを聞きながら学生2人が船のツアーについて話しています。", "lines": [{"k": "spk", "s": "ラジオ", "t": "今日は東湾から出発する観光クルーズの中で、船の上から夜景が楽しめるコースを4つご紹介します。1番のコースは緑川を登って帰ってくるコースです。ライトアップされた橋をいくつもくぐります。2番のコースは海沿いの観覧車や高層ビル群が美しく浮かび上がる景色が楽しめます。3番のコースはルートは2番と同じですが、クルまんきつーズ中に本格的なコース料理が楽しめます。4番のコースは工業地帯の夜景が満喫でえんとつきます。煙突から噴き出す水蒸気が幻想的で、SF映画のようだと評判です。なお、こちらのコースのみ不定期ですが、その他のコースは毎週末運航されています。詳細はホームページをご覧ください。"}, {"k": "spk", "s": "男", "t": "面白そう。今週末行ってみない?ライトアップされた橋もいいけど、工業地帯もいいね。"}, {"k": "spk", "s": "女", "t": "どっちも良さそうだね。一つは不定期運航でしょ?今週末やってるのかサイト見てみるね。あー、ないみたい。"}, {"k": "spk", "s": "男", "t": "じゃあ、決まりだね。"}, {"k": "spk", "s": "女", "t": "うん。あ、来月、家族が遊びに来るんだけど、その時も行こうかな。ビルとか観覧車とかの夜景喜びそうだから、それがいいな。"}, {"k": "spk", "s": "男", "t": "家族と船の上で食事ができるのいいんじゃない?"}, {"k": "spk", "s": "女", "t": "それも魅力的だけど、食べながらだと景色がゆっくり楽しめないから。"}, {"k": "q", "t": "質問12人は今週末どのコースに行くと言っていますか。(解答1)"}, {"k": "q", "t": "質問2  女の学生は来月家族とどのコースに行きたいと言っていますか。(解答2)"}]}], "2026-07": [{"head": "商店街の会議で3人の店長が話しています。", "lines": [{"k": "spk", "s": "女1", "t": "あそこに大型スーパーができてから、この商店街から客足が遠のいてますよね。どうにか商店街を盛り上げていく方法を考えないと。"}, {"k": "spk", "s": "男", "t": "そうですね。ここは1つケーキ付けに何か大きいイベントとかはどうでしょうか？例えば、祭りをしたり、格安セールをしたり。"}, {"k": "spk", "s": "女1", "t": "うんうん、イベントは確かに活気づきますね。"}, {"k": "spk", "s": "女2", "t": "でも、それじゃ、一時的な効果しかないんじゃないですか？もっと継続的な何か、お客さんが何度も足を運んでくれるような。うーん、ポイント制を導入するとか、憩いの場を提供するとか・・・"}, {"k": "spk", "s": "男", "t": "ポイント制って買い物したら、ポイントがもらえて、貯まったら景品と交換できるというあれでしょ？うん、継続性は確かにあるけど、スーパーがもうやってるからなあ。"}, {"k": "spk", "s": "女1", "t": "そうですね。同じことをしてもね。ところで、さっき言ってたもう1つの憩いの場の提供っていうのは何ですか？"}, {"k": "spk", "s": "女2", "t": "ああ、町の皆さんが気軽に集まってコミュニケーションできるような場所を作るんです。商店街のあちこちにベンチを置いたらどうでしょう？すぐにでもできますよね。"}, {"k": "spk", "s": "女1", "t": "あー、なるほど、人が自然に集まるようになれば、商店街も活気づきますね。そうやって人を集めることが大事かな。イベントは様子を見てからまた検討しましょう。"}, {"k": "spk", "s": "男", "t": "そうですね。"}, {"k": "q", "t": "この商店街では、まずどんな工夫をすることにしましたか？"}, {"k": "ch", "t": "1.祭りを企画する"}, {"k": "ch", "t": "2.セールを実施する"}, {"k": "ch", "t": "3.ポイント制を導入する"}, {"k": "ch", "t": "4.ベンチを設置する"}]}, {"head": "体育大学で先生が選択コースについて話しています。", "lines": [{"k": "spk", "s": "先生", "t": "えー、皆さんは来年2年次からは選択コースに分かれます。コースは全部で4つありますので、各自その中から1つ選んでください。手元の資料をご覧ください。コース1はプロを目指すスポーツ選手の指導者育成を目的としています。トレーニングのノウハウの他に、スポーツ心理も学びます。コース2は小中学生のスポーツの指導者を育てるコースです。小学生や中学生の健やかな成長のために、体や心理的な特徴を理解し、指導できる人を育てることが目的です。コース3は子供から大人まで幅広い世代の健康づくりのための指導について学ぶコースです。運動施設などの管理に必要なノウハウも学びます。コース4では、高齢者を対象とする運動指導について学びます。最近では健康維持のために運動をする高齢者も多く、高齢者専門のトレーナーの需要が増えています。"}, {"k": "spk", "s": "女", "t": "どのコースにしようかな。"}, {"k": "spk", "s": "男", "t": "山本さんは子供が好きだから、子供の指導が学べるのがいいんじゃない？小学校の体育の教員免許取るつもりだって言ってたよね。"}, {"k": "spk", "s": "女", "t": "うーん、それは将来の保険というかなんというか、特に夢ってわけじゃないんだ。"}, {"k": "spk", "s": "男", "t": "そうなんだ。僕は今バスケやってて、できればプロ似って思ってるけど、そう簡単にはなれないだろうし、将来のことを考えると、選手としての自分の経験を生かせるコースがいいな。プレイヤーの気持ちとか、心の状態みたいなものにも興味あるし。"}, {"k": "spk", "s": "女", "t": "そっか、私はスポーツを通してみんなの健康づくりに関わる仕事ができればいいなって思ってるんだ。最近、母が地域の運動教室に通うようになってね。体の調子が良くなって、友達も増えたって、何だか楽しそうなの。"}, {"k": "spk", "s": "男", "t": "ふーん。"}, {"k": "spk", "s": "女", "t": "色んな世代の人がスポーツを楽しめる場が作れたらいいなって思ってるんだ。うん、このコースにしよう。"}, {"k": "q", "t": "質問1 男の学生はどのコースを選択しますか？"}, {"k": "q", "t": "質問2 女の学生はどのコースを選択しますか？"}]}]};
